DROP TABLE IF EXISTS `假人_能力設置`;
CREATE TABLE `假人_能力設置`  (
  `class_id` int(2) NOT NULL COMMENT '職業ID (0:王族, 1:騎士, 2:妖精, 3:法師, 4:黑妖, 5:龍騎, 6:幻術)',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '備註(職業名稱)',
  `lvl_min` int(5) NULL DEFAULT 50 COMMENT '等級最小值',
  `lvl_max` int(5) NULL DEFAULT 80 COMMENT '等級最大值',
  `lawful_min` int(10) NULL DEFAULT 0 COMMENT '正義最小值',
  `lawful_max` int(10) NULL DEFAULT 32767 COMMENT '正義最大值',
  `hp_min` int(10) NULL DEFAULT 1000 COMMENT '血量最小值',
  `hp_max` int(10) NULL DEFAULT 2000 COMMENT '血量最大值',
  `mp_min` int(10) NULL DEFAULT 100 COMMENT '魔量最小值',
  `mp_max` int(10) NULL DEFAULT 500 COMMENT '魔量最大值',
  `ac_min` int(5) NULL DEFAULT -50 COMMENT '防禦最小值 (數值越小防禦越高)',
  `ac_max` int(5) NULL DEFAULT -80 COMMENT '防禦最大值',
  `str_add` int(3) NULL DEFAULT 0 COMMENT '力量(額外增加)',
  `dex_add` int(3) NULL DEFAULT 0 COMMENT '敏捷(額外增加)',
  `con_add` int(3) NULL DEFAULT 0 COMMENT '體質(額外增加)',
  `int_add` int(3) NULL DEFAULT 0 COMMENT '智力(額外增加)',
  `wis_add` int(3) NULL DEFAULT 0 COMMENT '精神(額外增加)',
  `cha_add` int(3) NULL DEFAULT 0 COMMENT '魅力(額外增加)',
  `sp_add` int(3) NULL DEFAULT 0 COMMENT '魔攻(額外增加)',
  `dmg_add` int(3) NULL DEFAULT 0 COMMENT '物理攻擊(額外增加)',
  PRIMARY KEY (`class_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

