-- ----------------------------
-- Table structure for 假人_自動召喚
-- ----------------------------
DROP TABLE IF EXISTS `假人_自動召喚`;
CREATE TABLE `假人_自動召喚`  (
  `id` int(5) NOT NULL AUTO_INCREMENT COMMENT '流水號',
  `is_enable` int(1) NULL DEFAULT 1 COMMENT '0:關閉, 1:開啟',
  `mapid` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '放置的地圖',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '注解',
  `x` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '如設定0 則代表該地圖隨機',
  `y` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '如設定0 則代表該地圖隨機',
  `range` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '設定的座標範圍X格內隨機點',
  `x_min` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'x/y/range全為0時使用：矩形起點X',
  `y_min` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'x/y/range全為0時使用：矩形起點Y',
  `x_max` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'x/y/range全為0時使用：矩形終點X',
  `y_max` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'x/y/range全為0時使用：矩形終點Y；四欄全0代表全地圖',
  `second` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '每幾秒放置幾隻->秒數設定',
  `count` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '每幾秒放置幾隻->數量設定',
  `life_time` int(10) NULL DEFAULT 0 COMMENT '存活秒數, 0為常駐',
  `de_max` int(10) UNSIGNED NOT NULL DEFAULT 50 COMMENT '該地圖最大生成數量限制',
  `ai_type` int(2) NOT NULL DEFAULT 0 COMMENT '0=發呆, 1=商店, 2=釣魚, 3=巡邏, 4=狩獵,6=無差別戰鬥',
  `is_morph` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否隨機變身(0:否 1:是)',
  `is_doll` int(1) NULL DEFAULT 0 COMMENT '是否攜帶娃娃',
  `use_pet` int(1) NULL DEFAULT 0 COMMENT '是否攜帶寵物 (0=否, 1=是)',
  `use_state` int(1) NULL DEFAULT 0 COMMENT '是否開啟自動狀態(0關/1開)',
  `use_state_chance` int(3) NULL DEFAULT 30 COMMENT '施放機率(%)',
  `use_state_time` int(5) NULL DEFAULT 30 COMMENT '檢查間隔(秒)',
  `de_set_id` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '假人_設置狀態的id號 \",\"間格',
  PRIMARY KEY (`id`, `second`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 103 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

