  `class_id` int(2) NOT NULL DEFAULT 0 COMMENT '職業(0:王族,1:騎士,2:妖精,3:法師,4:黑妖,5:龍騎,6:幻術)',
  `weapon_type` int(2) NOT NULL DEFAULT 0 COMMENT '0:空手, 1:單手劍, 2:匕首, 3:雙手劍, 4:弓, 5:雙手矛, 6:單手斧, 7:單手魔杖, 11:鋼爪, 12:雙刀, 13:單手弓 ,14:單手矛, 15:雙手斧, 16:雙手魔杖, 17:奇古獸, 18:鎖鏈劍',
  `poly_list` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '變身清單,分隔(0=不變身)',
