  `De_pet` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '寵物設定 (格式: 類型;NPCID;數量,) (類型1=寵物 2=招喚物)範例: 1;45034;3,2;81219;2',
  `akk_skill` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '攻擊技能權重設置(例如: 0,0,1,4)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 78 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

