  `流水號` int(11) NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `獲得能力時的訊息` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
