  `魅力` int(11) NOT NULL DEFAULT 0,
  `防禦` int(11) NOT NULL DEFAULT 0,
  `血量` int(11) NOT NULL DEFAULT 0,
  `魔量` int(11) NOT NULL DEFAULT 0,
  `回血量` int(11) NOT NULL DEFAULT 0,
  `回魔量` int(11) NOT NULL DEFAULT 0,
  `近距離傷害` int(11) NOT NULL DEFAULT 0,
  `遠距離傷害` int(11) NOT NULL DEFAULT 0,
