-- ----------------------------
-- Table structure for 卡冊變身卡片能力登入
-- ----------------------------
DROP TABLE IF EXISTS `卡冊變身卡片能力登入`;
CREATE TABLE `卡冊變身卡片能力登入`  (
  `流水號` int(11) NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `獲得能力時的訊息` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取得卡片時顯示的訊息',
  `對話檔指令` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '對應按鈕動作，如 do_poly_2',
  `任務編號` int(11) NOT NULL DEFAULT 0 COMMENT '玩家任務 ID，用於判斷是否已收藏',
  `變身編號` int(11) NOT NULL DEFAULT 0 COMMENT 'polymorphs 表中的變身 ID',
  `變身時效` int(11) NOT NULL DEFAULT 0 COMMENT '變身持續秒數，0=永久',
  `力量` int(11) NOT NULL DEFAULT 0 COMMENT 'STR 加成',
  `敏捷` int(11) NOT NULL DEFAULT 0 COMMENT 'DEX 加成',
  `體質` int(11) NOT NULL DEFAULT 0 COMMENT 'CON 加成',
  `智力` int(11) NOT NULL DEFAULT 0 COMMENT 'INT 加成',
  `精神` int(11) NOT NULL DEFAULT 0 COMMENT 'WIS 加成',
  `魅力` int(11) NOT NULL DEFAULT 0 COMMENT 'CHA 加成',
  `血量` int(11) NOT NULL DEFAULT 0 COMMENT 'HP 加成',
  `魔量` int(11) NOT NULL DEFAULT 0 COMMENT 'MP 加成',
  `card_grade` int(11) NOT NULL DEFAULT 1 COMMENT '卡片級別 1~7，用於分類顯示',
  `consume_item_id` int(11) NOT NULL DEFAULT 0 COMMENT '自動變身消耗道具 ID，0 不消耗',
  `consume_count` int(11) NOT NULL DEFAULT 0 COMMENT '每次變身消耗數量',
  `完成img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '已收藏：圖檔路徑(對話檔 #偶數變數，如 polyimg/xxx.bmp)',
  `未解img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '未收藏：圖檔路徑(同上，通常為灰階或問號圖)',
  PRIMARY KEY (`流水號`) USING BTREE,
  UNIQUE INDEX `uk_action`(`對話檔指令`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 220 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '變身卡片能力登入' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 卡冊變身卡片能力登入
