  `需求的玩家任務編號` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '逗號分隔的任務 ID，如 550000,550001',
  `力量` int(11) NOT NULL DEFAULT 0,
  `敏捷` int(11) NOT NULL DEFAULT 0,
  `體質` int(11) NOT NULL DEFAULT 0,
  `智力` int(11) NOT NULL DEFAULT 0,
  `精神` int(11) NOT NULL DEFAULT 0,
  `魅力` int(11) NOT NULL DEFAULT 0,
  `血量` int(11) NOT NULL DEFAULT 0,
  `魔量` int(11) NOT NULL DEFAULT 0,
  `回血量` int(11) NOT NULL DEFAULT 0,
  `回魔量` int(11) NOT NULL DEFAULT 0,
  `近距離傷害` int(11) NOT NULL DEFAULT 0,
  `遠距離傷害` int(11) NOT NULL DEFAULT 0,
  `近距離命中` int(11) NOT NULL DEFAULT 0,
  `遠戰攻擊命中` int(11) NOT NULL DEFAULT 0,
  `物理減免傷害` int(11) NOT NULL DEFAULT 0,
  `魔法減免傷害` int(11) NOT NULL DEFAULT 0,
  `魔攻` int(11) NOT NULL DEFAULT 0,
  `魔法命中` int(11) NOT NULL DEFAULT 0,
  `魔法防禦` int(11) NOT NULL DEFAULT 0,
  `火屬性防禦` int(11) NOT NULL DEFAULT 0,
  `水屬性防禦` int(11) NOT NULL DEFAULT 0,
  `風屬性防禦` int(11) NOT NULL DEFAULT 0,
  `地屬性防禦` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`流水號`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '變身卡套組能力' ROW_FORMAT = COMPACT;

