-- ----------------------------
DROP TABLE IF EXISTS `卡冊_●●●●●●●`;
CREATE TABLE `卡冊_●●●●●●●`  (
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = COMPACT;

