-- ----------------------------

-- ----------------------------
-- Table structure for 守護星盤_升級控制
-- ----------------------------
DROP TABLE IF EXISTS `守護星盤_升級控制`;
CREATE TABLE `守護星盤_升級控制`  (
  `id` int(11) NOT NULL COMMENT '唯一流水號(建議 type*1000 + node_id)',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '能力文字說明(給開發者與玩家看)',
  `type` int(11) NOT NULL COMMENT '星盤種類(1~5)',
  `node_id` int(255) NOT NULL COMMENT '該星盤的節點編號(1~30)',
  `require_node_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '前置節點要求(填0無要求)',
  `power_ids` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '該節點提供選擇的能力ID清單(如 1001,1002 供二選一)',
  `img_on` int(11) NOT NULL DEFAULT 0 COMMENT '啟用狀態的圖片編號(對應html中的 action)',
  `img_off` int(11) NOT NULL DEFAULT 0 COMMENT '未啟用狀態的圖片編號',
  `cost_item_id` int(11) NOT NULL DEFAULT 0 COMMENT '需求道具ID(如40308 天幣或星盤點數)',
  `cost_count` int(11) NOT NULL DEFAULT 0 COMMENT '需求道具數量',
  `prob` int(11) NOT NULL DEFAULT 100 COMMENT '成功機率(1~100)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '星盤節點規則設定' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 守護星盤_升級控制
-- ----------------------------

-- ----------------------------
-- Table structure for 守護星盤_能力設置
-- ----------------------------
DROP TABLE IF EXISTS `守護星盤_能力設置`;
CREATE TABLE `守護星盤_能力設置`  (
  `id` int(11) NOT NULL COMMENT '能力代碼',
  `classname` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '能力類型(如 PASSIVE_STR, ACTIVE_DMG)',
  `value_main` int(11) NOT NULL DEFAULT 0 COMMENT '主數值',
  `probability` int(11) NOT NULL DEFAULT 0 COMMENT '觸發機率(1~100)',
  `interval_time` int(11) NOT NULL DEFAULT 0 COMMENT '間隔時間(秒)',
  `passive_skill_id` int(11) NOT NULL DEFAULT 0 COMMENT '被動技能ID',
  `mode` int(11) NOT NULL DEFAULT 0 COMMENT '模式(1=Dmg, 2=Redux, 3=Heal)',
  `attr_type` int(11) NOT NULL DEFAULT 0 COMMENT '屬性傷害類型',
  `gfx_id` int(11) NOT NULL DEFAULT 0 COMMENT '觸發動畫特效編號',
  `gfx_target` int(11) NOT NULL DEFAULT 0 COMMENT '特效對象',
  `value_sub` int(11) NOT NULL DEFAULT 0 COMMENT '副數值',
  `trigger_skill_id` int(11) NOT NULL DEFAULT 0 COMMENT '觸發技能ID',
  `item_id` int(11) NOT NULL DEFAULT 0 COMMENT '關聯道具ID',
  `item_count` int(11) NOT NULL DEFAULT 0 COMMENT '道具數量',
  `status_id` int(11) NOT NULL DEFAULT 0 COMMENT '狀態ID',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '能力文字說明(給開發者與玩家看)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '星盤能力設計底板' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 守護星盤_能力設置
-- ----------------------------

