-- ----------------------------
-- Table structure for 活動_五星樂透
-- ----------------------------
DROP TABLE IF EXISTS `活動_五星樂透`;
CREATE TABLE `活動_五星樂透`  (
  `id` tinyint(4) NOT NULL COMMENT '2=二星 … 5=五星',
  `獎金佔比` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '該星級可分配總獎池之百分比（2～5 合計須為100）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '五星樂透各星級獎金池占比' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 活動_五星樂透
-- ----------------------------

-- ----------------------------
-- Table structure for 活動_奇岩賽狗
-- ----------------------------
DROP TABLE IF EXISTS `活動_奇岩賽狗`;
CREATE TABLE `活動_奇岩賽狗`  (
  `id` tinyint(4) NOT NULL COMMENT '跑道編號 (1~5；對應內部 _xId 0~4)',
  `最小賠率` decimal(4, 1) NOT NULL COMMENT '該跑道每場可骰出的最低顯示賠率 (>1.0)',
  `最大賠率` decimal(4, 1) NOT NULL COMMENT '該跑道每場可骰出的最高顯示賠率 (>= 最小賠率)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '奇岩賭場(賽狗)隨機賠率區間' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 活動_奇岩賽狗
-- ----------------------------

-- ----------------------------
-- Table structure for 活動_快樂骰寶
-- ----------------------------
DROP TABLE IF EXISTS `活動_快樂骰寶`;
CREATE TABLE `活動_快樂骰寶`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '流水編號',
  `玩法` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '玩法名稱（說明用，不影響結算）',
  `賠率` int(10) UNSIGNED NOT NULL DEFAULT 1 COMMENT '結算倍率（唯一影響核心的欄位）',
  `var_id` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '對應 y_dice2 之 var 編號 #2～#13',
  `action` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'HTML action，與 y_dice2-c 相同',
  `img` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '客戶端 img 編號（紀錄用）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_action`(`action`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '快樂骰寶玩法與賠率對照' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 活動_快樂骰寶
-- ----------------------------

-- ----------------------------
-- Table structure for 活動_機智問答
-- ----------------------------
DROP TABLE IF EXISTS `活動_機智問答`;
CREATE TABLE `活動_機智問答`  (
  `quiz_id` int(10) UNSIGNED NOT NULL,
  `show_quiz` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `optionA` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `optionB` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `optionC` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `optionD` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `answer` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  `獎勵item_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '答對派獎道具編號',
  PRIMARY KEY (`quiz_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = sjis COLLATE = sjis_japanese_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of 活動_機智問答
-- ----------------------------

-- ----------------------------
-- Table structure for 活動_死亡競賽
-- ----------------------------
DROP TABLE IF EXISTS `活動_死亡競賽`;
CREATE TABLE `活動_死亡競賽`  (
  `id` int(11) NOT NULL COMMENT '開戰時場上真人玩家數（1～20）',
  `獎勵道具編號` int(11) NOT NULL COMMENT '該人數時優勝可獲得之道具模板編號',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '死亡競賽依參賽人數對應之優勝獎勵' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 活動_死亡競賽
-- ----------------------------

-- ----------------------------
-- Table structure for 活動_無限大賽怪物
-- ----------------------------
DROP TABLE IF EXISTS `活動_無限大賽怪物`;
CREATE TABLE `活動_無限大賽怪物`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `ub_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `pattern` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `group_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `location` varchar(19) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `npc_templateid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `spawn_delay` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `seal_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1120 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

