-- Records of 活動_無限大賽設置
-- ----------------------------

-- ----------------------------
-- Table structure for 活動_角子老虎
-- ----------------------------
DROP TABLE IF EXISTS `活動_角子老虎`;
CREATE TABLE `活動_角子老虎`  (
  `ID` int(11) NOT NULL COMMENT '符號編號 0～8',
  `圖片編號` int(11) NOT NULL DEFAULT 0 COMMENT '客戶端 img 圖號（未填時伺服器採 3780+ID）',
  `圖案名稱` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '顯示用名稱',
  `機率權重` int(11) NOT NULL DEFAULT 0 COMMENT '萬分比權重；全表加總應為 10000',
  `單線賠率` int(11) NOT NULL DEFAULT 0 COMMENT '單條連線（三格相同）時的倍率',
  `全線賠率` int(11) NOT NULL DEFAULT 0 COMMENT '九格全相同時的倍率（優先於單線）',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '活動_角子老虎（九宮格角子機圖案設定）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 活動_角子老虎
-- ----------------------------

-- ----------------------------
-- Table structure for 活動_賓果連線
-- ----------------------------
DROP TABLE IF EXISTS `活動_賓果連線`;
CREATE TABLE `活動_賓果連線`  (
  `id` int(11) NOT NULL COMMENT '列編號：0～24 對應球號列；25＝中獎標記列',
  `數字` int(11) NOT NULL COMMENT '賓果球號 1～25；中獎列建議填 0',
  `img` int(11) NOT NULL COMMENT '客戶端圖檔編號（對應 HTML var img src）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '賓果樂透：球號／中獎圖對照表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 活動_賓果連線
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_●●●●●●●
-- ----------------------------
DROP TABLE IF EXISTS `系統_●●●●●●●`;
CREATE TABLE `系統_●●●●●●●`  (
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_●●●●●●●
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_劇情任務
-- ----------------------------
DROP TABLE IF EXISTS `系統_劇情任務`;
CREATE TABLE `系統_劇情任務`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '規則主鍵',
  `quest_id` int(11) NOT NULL COMMENT '對齊舊 server_quest.id（101-144）',
  `quest_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `event_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'NPC_TALK/NPC_ACTION',
  `enabled` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1=啟用',
  `limit_class` int(11) NOT NULL DEFAULT 0 COMMENT '職業 bitmask，0=不限',
  `limit_min_lvl` int(11) NOT NULL DEFAULT 0 COMMENT '最低等級',
  `limit_max_lvl` int(11) NOT NULL DEFAULT 0 COMMENT '最高等級，0=不限',
  `pre_quest_id` int(11) NOT NULL DEFAULT 0 COMMENT '前置任務需完成（255或自訂1）',
  `npc_id` int(11) NOT NULL DEFAULT 0 COMMENT 'NPC_ACTION/ESCORT 來源；ON_KILL=怪物ID',
  `action_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'HTML 按鈕 action',
  `require_step_min` int(11) NOT NULL DEFAULT 0 COMMENT '進行中 step 下限',
  `require_step_max` int(11) NOT NULL DEFAULT 0 COMMENT '進行中 step 上限；0=不限上限',
  `require_gfx` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '變身 gfx 多值逗號；! 前綴=NOT',
  `require_items` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '僅檢查 id,count;...',
  `consume_items` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '消耗 id,count;...',
  `give_items` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '給予 id,count;...',
  `set_step` int(11) NOT NULL DEFAULT 0 COMMENT '成功後 step；0=不變；255=完成',
  `start_quest` tinyint(4) NOT NULL DEFAULT 0 COMMENT '1=接取寫 step=1＋單槽檢查',
  `html` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '執行後可選再開 HTML',
  `params` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'key=value;...',
  `priority` int(11) NOT NULL DEFAULT 0 COMMENT '同分決勝，大者優先',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_story_quest_id`(`quest_id`) USING BTREE,
  INDEX `idx_story_event_npc_action`(`event_type`, `npc_id`, `action_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41000002 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '官方劇情/試煉步驟規則' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_劇情任務
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_受擊無動作gfx
-- ----------------------------
DROP TABLE IF EXISTS `系統_受擊無動作gfx`;
CREATE TABLE `系統_受擊無動作gfx`  (
  `gfx_id` int(11) NOT NULL COMMENT 'NPC 外形編號 (getTempCharGfx)',
  `note` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '備註',
  PRIMARY KEY (`gfx_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'NPC 受擊時不播受傷動作' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_受擊無動作gfx
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_強化機率
-- ----------------------------
DROP TABLE IF EXISTS `系統_強化機率`;
CREATE TABLE `系統_強化機率`  (
  `over_level` int(11) NOT NULL COMMENT '超出安定值的階級 (1~N，可延伸)',
  `weapon` int(11) NOT NULL DEFAULT 33 COMMENT '武器在該階級的成功機率 (1~100)',
  `armor` int(11) NOT NULL DEFAULT 33 COMMENT '防具在該階級的成功機率',
  `accessory` int(11) NOT NULL DEFAULT 33 COMMENT '飾品在該階級的成功機率',
  PRIMARY KEY (`over_level`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '裝備過安定強化機率表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_強化機率
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_死亡噴出控制
-- ----------------------------
DROP TABLE IF EXISTS `系統_死亡噴出控制`;
CREATE TABLE `系統_死亡噴出控制`  (
  `itemid` int(10) UNSIGNED NOT NULL COMMENT '道具編號 (對應 item 表)',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '道具名稱（備註用，方便管理）',
  `drop_setting` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '1=必噴落地 2=不噴 3=必噴回收 4=隨機噴出時回收',
  PRIMARY KEY (`itemid`) USING BTREE,
  INDEX `idx_drop_setting`(`drop_setting`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '死亡懲罰噴裝外控：1=必噴 2=不噴' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_死亡噴出控制
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_火神熔煉
-- ----------------------------
DROP TABLE IF EXISTS `系統_火神熔煉`;
CREATE TABLE `系統_火神熔煉`  (
  `道具編號` int(11) NOT NULL COMMENT '武器/防具 item_id',
  `note` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '備註欄位（開發/管理用）',
  `強化0` int(11) NOT NULL DEFAULT 0,
  `強化1` int(11) NOT NULL DEFAULT 0,
  `強化2` int(11) NOT NULL DEFAULT 0,
  `強化3` int(11) NOT NULL DEFAULT 0,
  `強化4` int(11) NOT NULL DEFAULT 0,
  `強化5` int(11) NOT NULL DEFAULT 0,
  `強化6` int(11) NOT NULL DEFAULT 0,
  `強化7` int(11) NOT NULL DEFAULT 0,
  `強化8` int(11) NOT NULL DEFAULT 0,
  `強化9` int(11) NOT NULL DEFAULT 0,
  `強化10` int(11) NOT NULL DEFAULT 0,
  `強化11` int(11) NOT NULL DEFAULT 0,
  `強化12` int(11) NOT NULL DEFAULT 0,
  `強化13` int(11) NOT NULL DEFAULT 0,
  `強化14` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`道具編號`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '火神熔煉：裝備分解結晶數' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_火神熔煉
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_火神製作
-- ----------------------------
DROP TABLE IF EXISTS `系統_火神製作`;
CREATE TABLE `系統_火神製作`  (
  `成品編號` int(11) NOT NULL COMMENT '成功 item_id',
  `note` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '備註欄位（開發/管理用）',
  `動作編號` int(11) NOT NULL COMMENT 'MakeInfo 第1欄',
  `結晶數量` int(11) NOT NULL DEFAULT 0 COMMENT '消耗 80029',
  `契約數量` int(11) NOT NULL DEFAULT 0 COMMENT '消耗 80028',
  `成功率` int(11) NOT NULL DEFAULT 0 COMMENT '基礎成功率%',
  `tbl-atcion` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '備註欄位（開發/管理用）',
  PRIMARY KEY (`動作編號`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '火神合成：伺服器確認用' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_火神製作
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_等級送禮
-- ----------------------------
DROP TABLE IF EXISTS `系統_等級送禮`;
CREATE TABLE `系統_等級送禮`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `level` int(11) NOT NULL COMMENT '達標等級',
  `class_id` int(11) NOT NULL DEFAULT 127 COMMENT '職業限制(位元): 1王族 2騎士 4精靈 8法師 16黑妖 32龍騎 64幻術 127全職業',
  `item_id` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '道具ID，多組以逗號分隔',
  `count` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '數量，多組以逗號分隔',
  `enchant` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '強化值，多組以逗號分隔',
  `quest_id` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '領取紀錄用任務ID，多組以逗號分隔(step=1表示已領)',
  `message` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '發送給玩家的提示訊息(可選)',
  PRIMARY KEY (`id`, `level`, `class_id`) USING BTREE,
  INDEX `idx_level`(`level`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '升級獎勵設定' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_等級送禮
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_自訂任務
-- ----------------------------
DROP TABLE IF EXISTS `系統_自訂任務`;
CREATE TABLE `系統_自訂任務`  (
  `quest_id` int(11) NOT NULL COMMENT '任務編號',
  `quest_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '任務名稱',
  `quest_group` int(11) NOT NULL DEFAULT 0 COMMENT '任務群組分類',
  `quest_group_order` int(11) NOT NULL DEFAULT 0 COMMENT '任務群組序列',
  `limit_class` int(11) NOT NULL DEFAULT 0 COMMENT '職業限制: 127=全職\r\n * 職業分類<br>\r\n * 王族可執行:1<br>\r\n * 騎士可執行:2<br>\r\n * 精靈可執行:4<br>\r\n * 法師可執行:8<br>\r\n * 黑暗精靈可執行:16<br>\r\n * 龍騎士可執行:32<br>\r\n * 幻術師可執行:64<br>',
  `limit_min_lvl` int(11) NOT NULL DEFAULT 0 COMMENT '最低等級',
  `limit_max_lvl` int(11) NOT NULL DEFAULT 0 COMMENT '最高等級 (0=不限)',
  `pre_quest_id` int(11) NOT NULL DEFAULT 0 COMMENT '前置任務 ID (0=無)',
  `check_inventory_items` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '接取時檢查道具，格式 itemId,count;itemId,count\r\n空=不檢查',
  `start_npc_id` int(11) NOT NULL DEFAULT 0 COMMENT '接取任務的 NPC ID',
  `start_action` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '接取時的 HTML 對話檔名',
  `end_npc_id` int(11) NOT NULL DEFAULT 0 COMMENT '回報任務的 NPC ID',
  `end_action` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '完成時的 HTML 對話檔名',
  `cancel_action` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '取消任務時的 HTML 對話檔名',
  `target_mobs` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '狩獵怪物，格式 npcId,count;npcId,count',
  `target_items` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '收集道具，格式 itemId,count;itemId,count',
  `target_map_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '指定地圖，格式 mapId,count;mapId,count',
  `reward_items` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '獎勵道具，格式 itemId,count;itemId,count',
  `del_on_restart` tinyint(4) NOT NULL DEFAULT 0 COMMENT '1=伺服器重啟時自動刪除任務, 0=保留',
  `msg_complete` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '任務完成時的顯示訊息',
  `quick_item_id` int(11) NOT NULL DEFAULT 0 COMMENT '快解所需道具 ID (0=不可快解)',
  `quick_count` int(11) NOT NULL DEFAULT 0 COMMENT '快解所需道具數量',
  PRIMARY KEY (`quest_id`) USING BTREE,
  INDEX `idx_quest_group`(`quest_group`, `quest_group_order`) USING BTREE,
  INDEX `idx_start_npc`(`start_npc_id`) USING BTREE,
  INDEX `idx_end_npc`(`end_npc_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'L1J 任務範本表 (Mega Table)' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_自訂任務
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_自訂收藏
-- ----------------------------
DROP TABLE IF EXISTS `系統_自訂收藏`;
CREATE TABLE `系統_自訂收藏`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '流水號',
  `quest` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '任務編號，對應 character_quests.quest_id',
  `html_page` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '群組，對應 HTML 的 檔名 例如:collect01',
  `html_slot` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '詳情連結 coll_<id>',
  `name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收藏名稱',
  `action_name` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'HTML 動作字串，如 test_01',
  `npc` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '關聯的 NPC 編號（npcid）',
  `material_items` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '需求材料道具 ID，多個以逗號分隔，例：40038,44070',
  `material_counts` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '需求材料數量，多個以逗號分隔，與 material_items 一一對應，例：10,1',
  `material_強化值` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '與 material_items 逗號對應；筆數須一致；-1不檢查',
  `Str` smallint(6) NULL DEFAULT 0 COMMENT '力量',
  `Dex` smallint(6) NULL DEFAULT 0 COMMENT '敏捷',
  `Con` smallint(6) NULL DEFAULT 0 COMMENT '體質',
  `Int` smallint(6) NULL DEFAULT 0 COMMENT '智力',
  `Wis` smallint(6) NULL DEFAULT 0 COMMENT '精神',
  `Cha` smallint(6) NULL DEFAULT 0 COMMENT '魅力',
  `Hp` int(11) NULL DEFAULT 0 COMMENT '生命值上限',
  `Mp` int(11) NULL DEFAULT 0 COMMENT '魔法值上限',
  `Hpr` smallint(6) NULL DEFAULT 0 COMMENT 'HP 回復',
  `Mpr` smallint(6) NULL DEFAULT 0 COMMENT 'MP 回復',
  `Hit` smallint(6) NULL DEFAULT 0 COMMENT '近距離命中',
  `Dmg` smallint(6) NULL DEFAULT 0 COMMENT '近距離傷害',
  `BowHit` smallint(6) NULL DEFAULT 0 COMMENT '遠距離命中',
  `BowDmg` smallint(6) NULL DEFAULT 0 COMMENT '遠距離傷害',
  `Ac` smallint(6) NULL DEFAULT 0 COMMENT '防禦力',
  `Mr` smallint(6) NULL DEFAULT 0 COMMENT '抗魔',
  `ReductionDmg` smallint(6) NULL DEFAULT 0 COMMENT '傷害減免',
  `Sp` smallint(6) NULL DEFAULT 0 COMMENT '魔法攻擊力',
  `MagicHit` smallint(6) NULL DEFAULT 0 COMMENT '魔法命中',
  `DefFire` smallint(6) NULL DEFAULT 0 COMMENT '火屬性防禦',
  `DefWater` smallint(6) NULL DEFAULT 0 COMMENT '水屬性防禦',
  `DefWind` smallint(6) NULL DEFAULT 0 COMMENT '風屬性防禦',
  `DefEarth` smallint(6) NULL DEFAULT 0 COMMENT '地屬性防禦',
  `Pierce` smallint(6) NULL DEFAULT 0 COMMENT '貫穿（無視硬皮怪減傷）',
  `Dodge` smallint(6) NULL DEFAULT 0 COMMENT '閃避率',
  `Er` smallint(6) NULL DEFAULT 0 COMMENT '遠距離迴避',
  `RegistFreeze` smallint(6) NULL DEFAULT 0 COMMENT '寒冰耐性',
  `RegistStone` smallint(6) NULL DEFAULT 0 COMMENT '石化耐性',
  `RegistSleep` smallint(6) NULL DEFAULT 0 COMMENT '睡眠耐性',
  `RegistBlind` smallint(6) NULL DEFAULT 0 COMMENT '暗黑耐性',
  `RegistStun` smallint(6) NULL DEFAULT 0 COMMENT '昏迷耐性',
  `RegistSustain` smallint(6) NULL DEFAULT 0 COMMENT '支撐耐性',
  `StunSuccess` smallint(6) NULL DEFAULT 0 COMMENT '暈眩成功率',
  `MagicDmgModifier` smallint(6) NULL DEFAULT 0 COMMENT '魔法傷害加成',
  `MagicDmgRedux` smallint(6) NULL DEFAULT 0 COMMENT '魔法傷害減免',
  `PotionRecovery` smallint(6) NULL DEFAULT 0 COMMENT '藥水恢復量增加',
  `PoisonResist` smallint(6) NULL DEFAULT 0 COMMENT '毒性抵抗',
  `PvpDmg` smallint(6) NULL DEFAULT 0 COMMENT 'PVP傷害加成',
  `PvpRedux` smallint(6) NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `DmgBoss` smallint(6) NULL DEFAULT 0 COMMENT '對BOSS傷害加成',
  `BossRedux` smallint(6) NULL DEFAULT 0 COMMENT '受到BOSS傷害減免(%)',
  `IgnoreReduction` smallint(6) NULL DEFAULT 0 COMMENT '無視傷害減免',
  `MeleeRedux` smallint(6) NULL DEFAULT 0 COMMENT '近距離傷害減免',
  `BowRedux` smallint(6) NULL DEFAULT 0 COMMENT '遠距離傷害減免',
  `AdenaRate` smallint(6) NULL DEFAULT 0 COMMENT '金幣獲取率(%)',
  `DropRate` smallint(6) NULL DEFAULT 0 COMMENT '掉寶獲取率(%)',
  `ExpRate` smallint(6) NULL DEFAULT 0 COMMENT '經驗獲取率(%)',
  `WeightReduction` smallint(6) NULL DEFAULT 0 COMMENT '重量減免(%)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_quest`(`quest`) USING BTREE,
  INDEX `idx_action`(`action_name`) USING BTREE,
  INDEX `idx_npc`(`npc`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 268 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '任務收藏能力表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_自訂收藏
-- ----------------------------

-- ----------------------------
-- Table structure for 系統_裝備贖回設置
-- ----------------------------
DROP TABLE IF EXISTS `系統_裝備贖回設置`;
CREATE TABLE `系統_裝備贖回設置`  (
  `Value` int(11) NOT NULL COMMENT '超安定值(強化等級-safeEnchant)',
  `NeedItem` int(11) NOT NULL COMMENT '贖回消耗道具ID',
  `NeedCount` bigint(20) NOT NULL COMMENT '贖回消耗數量',
  `Enabled` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1=啟用,0=停用',
  `Note` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '備註',
  PRIMARY KEY (`Value`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系統_裝備贖回設置' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 系統_裝備贖回設置
-- ----------------------------

-- ----------------------------
-- Table structure for 紋樣_●●●●●●●
-- ----------------------------
DROP TABLE IF EXISTS `紋樣_●●●●●●●`;
CREATE TABLE `紋樣_●●●●●●●`  (
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 紋樣_●●●●●●●
-- ----------------------------

-- ----------------------------
-- Table structure for 紋樣_機率設置
-- ----------------------------
DROP TABLE IF EXISTS `紋樣_機率設置`;
CREATE TABLE `紋樣_機率設置`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '流水號',
  `level` int(11) NOT NULL DEFAULT 0 COMMENT '紋樣等級(1~30)',
  `default_cost_item_id` int(11) NOT NULL DEFAULT 40308 COMMENT '消耗單位預設',
  `default_cost_count` int(11) NOT NULL DEFAULT 0 COMMENT '消耗單位數量',
  `up_1_prob` int(11) NOT NULL DEFAULT 0 COMMENT '升級1成功率(權重,總計100)',
  `up_2_prob` int(11) NOT NULL DEFAULT 0 COMMENT '升級2成功率(權重,總計100)',
  `up_3_prob` int(11) NOT NULL DEFAULT 0 COMMENT '升級3成功率(權重,總計100)',
  `down_1_prob` int(11) NOT NULL DEFAULT 0 COMMENT '倒扣成功率(權重,總計100,剩餘機率=失敗不倒扣)',
  `refresh_cost_item_id` int(11) NOT NULL DEFAULT 40308 COMMENT '刷新機率消耗單位',
  `refresh_cost_count` int(11) NOT NULL DEFAULT 0 COMMENT '刷新機率消耗單位數量',
  `refresh_max_bonus` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '10,5,3' COMMENT '刷新機制增加的最大值(針對+1, +2, +3)',
  `spr_action` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '3944' COMMENT '升級成功spr跑圖欄位(多個以逗號分隔)',
  `effect_id` int(11) NULL DEFAULT 0 COMMENT '升級成功特效抽獎欄位(PacketBox 83)',
  `success_msg` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '升級成功！' COMMENT '升級成功對話框訊息',
  `fail_msg` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '升級失敗！' COMMENT '升級失敗對話框訊息',
  `refresh_bonus_prob` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '30,20,10' COMMENT '刷新該增加值的機率(針對+1, +2, +3抽中的機率)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '紋樣系統升級機率表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 紋樣_機率設置
-- ----------------------------

-- ----------------------------
-- Table structure for 紋樣_能力設置
-- ----------------------------
DROP TABLE IF EXISTS `紋樣_能力設置`;
CREATE TABLE `紋樣_能力設置`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '流水號',
  `type` int(11) NOT NULL DEFAULT 1 COMMENT '紋樣種類(1~6)',
  `level` int(11) NOT NULL DEFAULT 0 COMMENT '紋樣等級',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '能力文字說明(給開發者與玩家看)',
  `img_id` int(11) NOT NULL DEFAULT 0 COMMENT '對應客戶端圖檔編號',
  `add_hp` int(11) NOT NULL DEFAULT 0 COMMENT '增加HP',
  `add_mp` int(11) NOT NULL DEFAULT 0 COMMENT '增加MP',
  `add_sp` int(11) NOT NULL DEFAULT 0 COMMENT '增加魔攻',
  `add_str` int(11) NOT NULL DEFAULT 0 COMMENT '增加力量',
  `add_dex` int(11) NOT NULL DEFAULT 0 COMMENT '增加敏捷',
  `add_con` int(11) NOT NULL DEFAULT 0 COMMENT '增加體質',
  `add_int` int(11) NOT NULL DEFAULT 0 COMMENT '增加智力',
  `add_wis` int(11) NOT NULL DEFAULT 0 COMMENT '增加精神',
  `add_cha` int(11) NOT NULL DEFAULT 0 COMMENT '增加魅力',
  `add_mr` int(11) NOT NULL DEFAULT 0 COMMENT '增加魔防',
  `add_ac` int(11) NOT NULL DEFAULT 0 COMMENT '增加防禦(減少AC)',
  `add_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '增加近戰傷害',
  `add_bow_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '增加遠攻傷害',
  `add_hit` int(11) NOT NULL DEFAULT 0 COMMENT '增加近戰命中',
  `add_bow_hit` int(11) NOT NULL DEFAULT 0 COMMENT '增加遠攻命中',
  `add_hpr` int(11) NOT NULL DEFAULT 0 COMMENT '增加HP回復',
  `add_mpr` int(11) NOT NULL DEFAULT 0 COMMENT '增加MP回復',
  `add_melee_redux` int(11) NOT NULL DEFAULT 0 COMMENT '近戰傷害減免',
  `add_bow_redux` int(11) NOT NULL DEFAULT 0 COMMENT '遠攻傷害減免',
  `add_pvp_dmg` int(11) NOT NULL DEFAULT 0 COMMENT 'PVP傷害加成',
  `add_pvp_redux` int(11) NOT NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `add_dmg_boss` int(11) NOT NULL DEFAULT 0 COMMENT '對BOSS傷害加成',
  `add_boss_redux` int(11) NOT NULL DEFAULT 0 COMMENT '受BOSS傷害減免',
  `add_ignore_reduction` int(11) NOT NULL DEFAULT 0 COMMENT '無視傷害減免',
  `add_adena_rate` int(11) NOT NULL DEFAULT 0 COMMENT '金幣掉落率加成',
  `add_drop_rate` int(11) NOT NULL DEFAULT 0 COMMENT '物品掉落率加成',
  `add_exp_rate` int(11) NOT NULL DEFAULT 0 COMMENT '經驗值加成',
  `add_def_fire` int(11) NOT NULL DEFAULT 0 COMMENT '火屬性防禦',
  `add_def_water` int(11) NOT NULL DEFAULT 0 COMMENT '水屬性防禦',
  `add_def_wind` int(11) NOT NULL DEFAULT 0 COMMENT '風屬性防禦',
  `add_def_earth` int(11) NOT NULL DEFAULT 0 COMMENT '地屬性防禦',
  `add_regist_freeze` int(11) NOT NULL DEFAULT 0 COMMENT '寒冰耐性',
  `add_regist_stone` int(11) NOT NULL DEFAULT 0 COMMENT '石化耐性',
  `add_regist_sleep` int(11) NOT NULL DEFAULT 0 COMMENT '睡眠耐性',
  `add_regist_blind` int(11) NOT NULL DEFAULT 0 COMMENT '暗黑耐性',
  `add_regist_stun` int(11) NOT NULL DEFAULT 0 COMMENT '昏迷耐性',
  `add_regist_sustain` int(11) NOT NULL DEFAULT 0 COMMENT '支撐耐性',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 187 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '紋樣系統配置表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 紋樣_能力設置
-- ----------------------------

-- ----------------------------
-- Table structure for 裝備_暗黑_屬性
-- ----------------------------
DROP TABLE IF EXISTS `裝備_暗黑_屬性`;
CREATE TABLE `裝備_暗黑_屬性`  (
  `config_id` int(10) NOT NULL COMMENT '配置ID (對應暗黑_機率)',
  `item_type` int(10) NOT NULL DEFAULT 1 COMMENT '1=武器, 2=防具, 3=飾品',
  `ability_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '能力枚舉 (Enum)',
  `min_value` int(10) NOT NULL DEFAULT 0 COMMENT '隨機最小值',
  `max_value` int(10) NOT NULL DEFAULT 0 COMMENT '隨機最大值',
  `note` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '中文說明',
  PRIMARY KEY (`config_id`, `ability_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '暗黑屬性池' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 裝備_暗黑_屬性
-- ----------------------------

-- ----------------------------
-- Table structure for 裝備_暗黑_機率
-- ----------------------------
DROP TABLE IF EXISTS `裝備_暗黑_機率`;
CREATE TABLE `裝備_暗黑_機率`  (
  `config_id` int(10) NOT NULL,
  `item_type` int(10) NOT NULL DEFAULT 1 COMMENT '1=武器, 2=防具, 3=飾品',
  `count` int(10) NOT NULL DEFAULT 1 COMMENT '給予屬性數量',
  `weight` int(10) NOT NULL DEFAULT 100 COMMENT '機率權重',
  `title` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '對應頭銜 (如: [破壞神])',
  INDEX `idx_config`(`config_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '暗黑屬性機率與頭銜配置' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 裝備_暗黑_機率
-- ----------------------------

