-- ----------------------------
-- Table structure for 裝備_特殊_套裝_能力
-- ----------------------------
DROP TABLE IF EXISTS `裝備_特殊_套裝_能力`;
CREATE TABLE `裝備_特殊_套裝_能力`  (
  `set_id` int(11) NOT NULL COMMENT '套裝編號',
  `piece_count` int(11) NOT NULL COMMENT '所需件數',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '套裝名稱',
  `poly_id` int(11) NULL DEFAULT 0 COMMENT '變身代號（0或-1表示無變身）',
  `message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '套裝完成訊息',
  `ac` int(11) NULL DEFAULT 0 COMMENT '防禦力增加',
  `add_str` int(11) NULL DEFAULT 0 COMMENT '力量增加',
  `add_dex` int(11) NULL DEFAULT 0 COMMENT '敏捷增加',
  `add_con` int(11) NULL DEFAULT 0 COMMENT '體質增加',
  `add_int` int(11) NULL DEFAULT 0 COMMENT '智力增加',
  `add_wis` int(11) NULL DEFAULT 0 COMMENT '精神增加',
  `add_cha` int(11) NULL DEFAULT 0 COMMENT '魅力增加',
  `add_hp` int(11) NULL DEFAULT 0 COMMENT 'HP增加',
  `add_mp` int(11) NULL DEFAULT 0 COMMENT 'MP增加',
  `add_hpr` int(11) NULL DEFAULT 0 COMMENT 'HP回復增加',
  `add_mpr` int(11) NULL DEFAULT 0 COMMENT 'MP回復增加',
  `add_sp` int(11) NULL DEFAULT 0 COMMENT '魔法攻擊力增加',
  `m_def` int(11) NULL DEFAULT 0 COMMENT '魔防增加',
  `add_hitup` int(11) NOT NULL DEFAULT 0 COMMENT '近距離命中增加',
  `add_dmgup` int(11) NULL DEFAULT 0 COMMENT '近距離傷害增加',
  `add_bow_hitup` int(11) NOT NULL DEFAULT 0 COMMENT '遠距離命中增加',
  `add_bow_dmgup` int(11) NULL DEFAULT 0 COMMENT '遠距離傷害增加',
  `damage_reduction` int(11) NULL DEFAULT 0 COMMENT '傷害減免',
  `add_er` int(11) NULL DEFAULT 0 COMMENT '遠距離迴避增加',
  `weight_reduction` int(11) NULL DEFAULT 0 COMMENT '負重減免',
  `defense_fire` int(11) NULL DEFAULT 0 COMMENT '火屬性防禦',
  `defense_water` int(11) NULL DEFAULT 0 COMMENT '水屬性防禦',
  `defense_wind` int(11) NULL DEFAULT 0 COMMENT '風屬性防禦',
  `defense_earth` int(11) NULL DEFAULT 0 COMMENT '地屬性防禦',
  `regist_freeze` int(11) NULL DEFAULT 0 COMMENT '寒冰耐性',
  `regist_stone` int(11) NULL DEFAULT 0 COMMENT '石化耐性',
  `regist_sleep` int(11) NULL DEFAULT 0 COMMENT '睡眠耐性',
  `regist_blind` int(11) NULL DEFAULT 0 COMMENT '暗黑耐性',
  `regist_stun` int(11) NULL DEFAULT 0 COMMENT '昏迷耐性',
  `regist_sustain` int(11) NULL DEFAULT 0 COMMENT '支撐耐性',
  `magic_dmg_modifier` int(11) NULL DEFAULT 0 COMMENT '魔法傷害加成',
  `magic_dmg_reduction` int(11) NULL DEFAULT 0 COMMENT '魔法傷害減免',
  `add_magic_hit` int(11) NULL DEFAULT 0 COMMENT '魔法命中增加',
  `add_pvp_dmg` int(11) NULL DEFAULT 0 COMMENT 'PVP 傷害加成',
  `add_pvp_redux` int(11) NULL DEFAULT 0 COMMENT 'PVP 傷害減免',
  `add_boss_dmg` int(11) NULL DEFAULT 0 COMMENT '對 BOSS 傷害加成',
  `add_boss_redux` int(11) NULL DEFAULT 0 COMMENT '受到 BOSS 傷害減免%',
  `add_ignore_reduction` int(11) NULL DEFAULT 0 COMMENT '無視傷害減免',
  `add_melee_redux` int(11) NULL DEFAULT 0 COMMENT '近距離傷害減免',
  `add_bow_redux` int(11) NULL DEFAULT 0 COMMENT '遠距離傷害減免',
  `add_adena_rate` int(11) NULL DEFAULT 0 COMMENT '金幣獲取率增加',
  `add_drop_rate` int(11) NULL DEFAULT 0 COMMENT '掉寶獲取率增加',
  `add_exp_rate` int(11) NULL DEFAULT 0 COMMENT '經驗獲取率增加',
  `add_potion_recovery` int(11) NULL DEFAULT 0 COMMENT '藥水恢復量增加',
  `add_stun_success` int(11) NOT NULL DEFAULT 0 COMMENT '暈眩成功率增加',
  `add_pierce` int(11) NULL DEFAULT 0 COMMENT '貫穿 (ItemAbility.PIERCE)',
  `add_dodge` int(11) NULL DEFAULT 0 COMMENT '閃避率 (ItemAbility.DODGE)',
  `add_poison_resist` int(11) NULL DEFAULT 0 COMMENT '毒性耐性 (ItemAbility.POISON_RESIST)',
  PRIMARY KEY (`set_id`, `piece_count`) USING BTREE,
  INDEX `idx_set_id`(`set_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '套裝加成資料表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 裝備_特殊_套裝_能力
-- ----------------------------

-- ----------------------------
-- Table structure for 裝備_特殊_魔石_魔法
-- ----------------------------
DROP TABLE IF EXISTS `裝備_特殊_魔石_魔法`;
CREATE TABLE `裝備_特殊_魔石_魔法`  (
  `item_id` int(11) NOT NULL COMMENT '魔法石物品ID (對應 etcitem)',
  `tier` int(11) NOT NULL DEFAULT 1 COMMENT '階級 (1=基礎, 2=Lv2...)',
  `name_suffix` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '名稱後綴 (建議2-3個中文字內)',
  `prob_success` int(11) NOT NULL DEFAULT 1000 COMMENT '升級成功機率 (1/1000)',
  `prob_fail_mode` int(11) NOT NULL DEFAULT 0 COMMENT '失敗處理: 0=無變化, 1=降級/移除, 2=銷毀裝備',
  `duration` int(11) NOT NULL DEFAULT 0 COMMENT '持續時間(秒), 0=永久',
  `proc_chance` int(11) NOT NULL DEFAULT 0 COMMENT '觸發機率 (1/1000)',
  `dmg_type` int(11) NOT NULL DEFAULT 0 COMMENT '傷害類型: 0=物理, 1=魔法(INT), 2=魔法(SP), 3=固定',
  `dmg_fix` int(11) NOT NULL DEFAULT 0 COMMENT '固定傷害',
  `dmg_rnd` int(11) NOT NULL DEFAULT 0 COMMENT '隨機傷害',
  `dmg_attr` int(11) NOT NULL DEFAULT 0 COMMENT '屬性: 1=地, 2=火, 4=水, 8=風',
  `area_size` int(11) NOT NULL DEFAULT 0 COMMENT '範圍半徑',
  `gfx_id` int(11) NOT NULL DEFAULT 0 COMMENT '特效ID',
  `skill_id` int(11) NOT NULL DEFAULT 0 COMMENT '技能ID',
  `hp_drain` int(11) NOT NULL DEFAULT 0 COMMENT '吸血值',
  `mp_drain` int(11) NOT NULL DEFAULT 0 COMMENT '吸魔值',
  `add_str` int(11) NOT NULL DEFAULT 0,
  `add_dex` int(11) NOT NULL DEFAULT 0,
  `add_int` int(11) NOT NULL DEFAULT 0,
  `add_wis` int(11) NOT NULL DEFAULT 0,
  `add_con` int(11) NOT NULL DEFAULT 0,
  `add_hp` int(11) NOT NULL DEFAULT 0,
  `add_mp` int(11) NOT NULL DEFAULT 0,
  `add_mr` int(11) NOT NULL DEFAULT 0,
  `add_sp` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`item_id`, `tier`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '魔法石系統設定' ROW_FORMAT = DYNAMIC;

