-- ----------------------------
-- Table structure for 裝備_weapon_屬性
-- ----------------------------
DROP TABLE IF EXISTS `裝備_weapon_屬性`;
CREATE TABLE `裝備_weapon_屬性`  (
  `id` int(10) UNSIGNED NOT NULL COMMENT '屬性ID (對應 attrEnchantKind: 1=地, 2=火, 4=水, 8=風, 16=光, 32=暗, 64=聖, 128=邪)',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '顯示在武器上的名稱',
  `stage` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '屬性階級 (請從1開始)',
  `type_dmg_passive` int(11) NOT NULL DEFAULT 0 COMMENT '常駐屬性傷害(受抗性影響) \r\n不受機率影響(刀刀有效)\r\n怪物懼怕=*50%傷害\r\n玩家抗性100%=免疫抗性傷害',
  `chance` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '衝過機率 (1/1000)',
  `probability` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '發動機率 (1/1000)',
  `type_gfx_id` int(11) NOT NULL DEFAULT 0 COMMENT '發動時的特效代號',
  `type_add_dmg_min` int(11) NOT NULL DEFAULT 0 COMMENT '額外傷害(固定值)',
  `type_add_dmg_max` int(11) NOT NULL DEFAULT 0 COMMENT '額外傷害(隨機值)',
  `type_drain_hp_min` int(11) NOT NULL DEFAULT 0 COMMENT '吸血固定值',
  `type_drain_hp_max` int(11) NOT NULL DEFAULT 0 COMMENT '吸血隨機值',
  `type_drain_mp_min` int(11) NOT NULL DEFAULT 0 COMMENT '吸魔固定值',
  `type_drain_mp_max` int(11) NOT NULL DEFAULT 0 COMMENT '吸魔隨機值',
  `type_dmgup` double NOT NULL DEFAULT 0 COMMENT '額外傷害倍率',
  `type_range` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '範圍傷害 (XX格)',
  `type_range_dmg` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '範圍傷害 (固定值)',
  PRIMARY KEY (`id`, `stage`) USING BTREE,
  INDEX `idx_id_stage`(`id`, `stage`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '武器屬性功能表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 裝備_weapon_屬性
-- ----------------------------

-- ----------------------------
-- Table structure for 裝備_weapon_屬性_copy1
