  `add_mp` int(11) NULL DEFAULT 0 COMMENT 'MP加成',
  `add_hpr` int(11) NULL DEFAULT 0 COMMENT 'HP回復增加',
  `add_mpr` int(11) NULL DEFAULT 0 COMMENT 'MP回復增加',
  `add_mr` int(11) NULL DEFAULT 0 COMMENT '魔法防禦加成',
  `add_sp` int(11) NULL DEFAULT 0 COMMENT '負重減輕',
  `add_hitup` int(11) NULL DEFAULT 0 COMMENT '近戰命中',
  `add_dmgup` int(11) NULL DEFAULT 0 COMMENT '近戰傷害',
  `add_bow_hitup` int(11) NULL DEFAULT 0 COMMENT '遠程命中',
  `add_bow_dmgup` int(11) NULL DEFAULT 0 COMMENT '遠程傷害',
  `add_magic_hit` int(11) NULL DEFAULT 0 COMMENT '魔法命中',
  `add_magic_dmg` int(11) NULL DEFAULT 0 COMMENT '魔法傷害加成',
  `add_ac` int(11) NULL DEFAULT 0 COMMENT 'AC加成',
  `add_reduction` int(11) NULL DEFAULT 0 COMMENT '傷害減免',
  `add_dodge` int(11) NULL DEFAULT 0 COMMENT '閃避率',
  `add_er` int(11) NULL DEFAULT 0 COMMENT '遠距離迴避',
  `add_pvp_dmg` int(11) NULL DEFAULT 0 COMMENT 'PVP傷害加成',
  `add_pvp_redux` int(11) NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `add_boss_dmg` int(11) NULL DEFAULT 0,
  `add_boss_redux` int(11) NULL DEFAULT 0,
  `add_pierce` int(11) NULL DEFAULT 0 COMMENT '貫穿',
  `add_stun_success` int(11) NULL DEFAULT 0 COMMENT '昏迷成功率',
  `add_ignore_reduction` int(11) NULL DEFAULT 0 COMMENT '無視減免',
