  PRIMARY KEY (`bless_id`, `weapon_type`) USING BTREE,
  INDEX `idx_bless_id`(`bless_id`) USING BTREE,
  INDEX `idx_weapon_type`(`weapon_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '武器祝福能力表' ROW_FORMAT = COMPACT;

