  `add_dodge` int(11) NULL DEFAULT 0 COMMENT '閃避率',
  `add_er` int(11) NULL DEFAULT 0 COMMENT '遠距離迴避',
  `add_pvp_dmg` int(11) NULL DEFAULT 0 COMMENT 'PVP傷害加成',
  `add_pvp_redux` int(11) NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `add_boss_dmg` int(11) NULL DEFAULT 0,
  `add_boss_redux` int(11) NULL DEFAULT 0,
  `add_pierce` int(11) NULL DEFAULT 0 COMMENT '貫穿',
  `add_stun_success` int(11) NULL DEFAULT 0 COMMENT '昏迷成功率',
  `add_ignore_reduction` int(11) NULL DEFAULT 0 COMMENT '無視減免',
  `add_potion_recovery` int(11) NULL DEFAULT 0 COMMENT '藥水恢復量增加',
  `add_poison_resist` int(11) NULL DEFAULT 0 COMMENT '毒性抵抗',
  `add_exp_rate` int(11) NULL DEFAULT 0 COMMENT '經驗值獲取率',
  `add_drop_rate` int(11) NULL DEFAULT 0 COMMENT '掉寶率',
  `add_adena_rate` int(11) NULL DEFAULT 0 COMMENT '金幣獲取率',
  PRIMARY KEY (`item_id`, `enchant_level`) USING BTREE,
  INDEX `idx_item_id`(`item_id`) USING BTREE,
  INDEX `idx_enchant_level`(`enchant_level`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '武器強化獎勵表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 裝備_weapon_enchant_指定
-- ----------------------------

-- ----------------------------
-- Table structure for 裝備_weapon_enchant_類型
-- ----------------------------
DROP TABLE IF EXISTS `裝備_weapon_enchant_類型`;
CREATE TABLE `裝備_weapon_enchant_類型`  (
  `over_enchant` int(11) NOT NULL COMMENT '過安定值 (強化等級 - 安定值)',
  `weapon_type` int(11) NOT NULL COMMENT '武器類型 (1=劍, 2=匕首, 3=雙手劍, 4=弓, 5=矛, 6=鎚, 7=魔杖, 8=斧, 11=鋼爪, 12=雙刀, 14=奇古獸, 15=鎖鍊劍, 16=鐵手甲, 17=雙頭矛, 18=雙劍)',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '備註說明',
  `add_dmg_small` int(11) NULL DEFAULT 0 COMMENT '小型目標傷害',
  `add_dmg_large` int(11) NULL DEFAULT 0 COMMENT '大型目標傷害',
  `add_str` int(11) NULL DEFAULT 0 COMMENT '力量加成',
  `add_dex` int(11) NULL DEFAULT 0 COMMENT '敏捷加成',
  `add_con` int(11) NULL DEFAULT 0 COMMENT '體質加成',
  `add_int` int(11) NULL DEFAULT 0 COMMENT '智力加成',
  `add_wis` int(11) NULL DEFAULT 0 COMMENT '精神加成',
  `add_cha` int(11) NULL DEFAULT 0 COMMENT '魅力加成',
  `add_hp` int(11) NULL DEFAULT 0 COMMENT 'HP加成',
  `add_mp` int(11) NULL DEFAULT 0 COMMENT 'MP加成',
  `add_hpr` int(11) NULL DEFAULT 0 COMMENT 'HP回復增加',
  `add_mpr` int(11) NULL DEFAULT 0 COMMENT 'MP回復增加',
  `add_mr` int(11) NULL DEFAULT 0 COMMENT '魔法防禦加成',
  `add_sp` int(11) NULL DEFAULT 0 COMMENT '負重減輕',
  `add_hitup` int(11) NULL DEFAULT 0 COMMENT '近戰命中',
  `add_dmgup` int(11) NULL DEFAULT 0 COMMENT '近戰傷害',
  `add_bow_hitup` int(11) NULL DEFAULT 0 COMMENT '遠程命中',
  `add_bow_dmgup` int(11) NULL DEFAULT 0 COMMENT '遠程傷害',
  `add_magic_hit` int(11) NULL DEFAULT 0 COMMENT '魔法命中',
  `add_magic_dmg` int(11) NULL DEFAULT 0 COMMENT '魔法傷害加成',
  `add_ac` int(11) NULL DEFAULT 0 COMMENT 'AC加成',
  `add_reduction` int(11) NULL DEFAULT 0 COMMENT '傷害減免',
  `add_dodge` int(11) NULL DEFAULT 0 COMMENT '閃避率',
  `add_er` int(11) NULL DEFAULT 0 COMMENT '遠距離迴避',
  `add_pvp_dmg` int(11) NULL DEFAULT 0 COMMENT 'PVP傷害加成',
  `add_pvp_redux` int(11) NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `add_boss_dmg` int(11) NULL DEFAULT 0,
  `add_boss_redux` int(11) NULL DEFAULT 0,
  `add_pierce` int(11) NULL DEFAULT 0 COMMENT '貫穿',
  `add_stun_success` int(11) NULL DEFAULT 0 COMMENT '昏迷成功率',
  `add_ignore_reduction` int(11) NULL DEFAULT 0 COMMENT '無視減免',
  `add_potion_recovery` int(11) NULL DEFAULT 0 COMMENT '藥水恢復量增加',
  `add_poison_resist` int(11) NULL DEFAULT 0 COMMENT '毒性抵抗',
  `add_exp_rate` int(11) NULL DEFAULT 0 COMMENT '經驗值獲取率',
  `add_drop_rate` int(11) NULL DEFAULT 0 COMMENT '掉寶率',
  `add_adena_rate` int(11) NULL DEFAULT 0 COMMENT '金幣獲取率',
  PRIMARY KEY (`over_enchant`, `weapon_type`) USING BTREE,
  INDEX `idx_over_enchant`(`over_enchant`) USING BTREE,
  INDEX `idx_weapon_type`(`weapon_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '武器通用過安定獎勵表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 裝備_weapon_enchant_類型
-- ----------------------------

-- ----------------------------
-- Table structure for 裝備_weapon_greater_類型
-- ----------------------------
DROP TABLE IF EXISTS `裝備_weapon_greater_類型`;
CREATE TABLE `裝備_weapon_greater_類型`  (
  `tier_id` int(11) NOT NULL COMMENT '階級ID (對應 character_items.greater)',
  `weapon_type` int(11) NOT NULL COMMENT '武器類型 (1=劍, 2=匕首...)',
  `裝備說明` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '說明',
  `chance` int(11) NULL DEFAULT 0 COMMENT '獲取機率/權重',
  `note` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '說明',
  `add_dmg_small` int(11) NULL DEFAULT 0 COMMENT '增加基礎小怪傷害',
  `add_dmg_large` int(11) NULL DEFAULT 0 COMMENT '增加基礎大怪傷害',
  `add_hit` int(11) NULL DEFAULT 0 COMMENT '近戰命中',
  `add_dmg` int(11) NULL DEFAULT 0 COMMENT '近戰傷害',
  `add_bow_hit` int(11) NULL DEFAULT 0 COMMENT '遠攻命中',
  `add_bow_dmg` int(11) NULL DEFAULT 0 COMMENT '遠攻傷害',
  `add_magic_hit` int(11) NULL DEFAULT 0 COMMENT '魔法命中',
  `add_magic_dmg` int(11) NULL DEFAULT 0 COMMENT '魔法傷害加成',
  `add_str` int(11) NULL DEFAULT 0,
  `add_dex` int(11) NULL DEFAULT 0,
  `add_con` int(11) NULL DEFAULT 0,
  `add_int` int(11) NULL DEFAULT 0,
  `add_wis` int(11) NULL DEFAULT 0,
  `add_cha` int(11) NULL DEFAULT 0,
  `add_hp` int(11) NULL DEFAULT 0,
  `add_mp` int(11) NULL DEFAULT 0,
  `add_hpr` int(11) NULL DEFAULT 0,
  `add_mpr` int(11) NULL DEFAULT 0,
  `add_mr` int(11) NULL DEFAULT 0 COMMENT '抗魔',
  `add_sp` int(11) NULL DEFAULT 0 COMMENT '魔攻',
  `add_reduction` int(11) NULL DEFAULT 0 COMMENT '傷害減免',
  `add_ignore_reduction` int(11) NULL DEFAULT 0 COMMENT '無視減免',
  `add_fire` int(11) NULL DEFAULT 0,
  `add_water` int(11) NULL DEFAULT 0,
  `add_wind` int(11) NULL DEFAULT 0,
  `add_earth` int(11) NULL DEFAULT 0,
  `add_pvp_dmg` int(11) NULL DEFAULT 0,
  `add_pvp_redux` int(11) NULL DEFAULT 0,
  `add_boss_dmg` int(11) NULL DEFAULT 0,
  `add_boss_redux` int(11) NULL DEFAULT 0,
  `add_stun_success` int(11) NULL DEFAULT 0 COMMENT '暈眩命中率',
  `add_potion_recovery` int(11) NULL DEFAULT 0 COMMENT '藥水恢復量%',
  `add_exp_rate` int(11) NULL DEFAULT 0 COMMENT '經驗加成%',
  `add_drop_rate` int(11) NULL DEFAULT 0 COMMENT '掉寶加成%',
  `add_adena_rate` int(11) NULL DEFAULT 0 COMMENT '金幣加成%',
  `add_pierce` int(11) NULL DEFAULT 0 COMMENT '貫穿 (ItemAbility.PIERCE)',
  PRIMARY KEY (`tier_id`, `weapon_type`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '武器階級能力設定' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of 裝備_weapon_greater_類型
-- ----------------------------

