DROP TABLE IF EXISTS `角色_●●●●●●●`;
CREATE TABLE `角色_●●●●●●●`  (
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 角色_●●●●●●●
-- ----------------------------

-- ----------------------------
-- Table structure for 角色_力量成長
-- ----------------------------
DROP TABLE IF EXISTS `角色_力量成長`;
CREATE TABLE `角色_力量成長`  (
  `id` int(11) NOT NULL COMMENT '力量值 (STR，1~127，等同流水排序)',
  `命中` int(11) NOT NULL DEFAULT 0 COMMENT '物理命中補正值',
  `傷害` int(11) NOT NULL DEFAULT 0 COMMENT '物理傷害補正值',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '力量外控：id=STR值，命中=命中補正，傷害=傷害補正' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 角色_力量成長
-- ----------------------------

-- ----------------------------
-- Table structure for 角色_敏捷成長
-- ----------------------------
DROP TABLE IF EXISTS `角色_敏捷成長`;
CREATE TABLE `角色_敏捷成長`  (
  `id` int(11) NOT NULL COMMENT '敏捷值 (DEX，1~127，等同流水排序)',
  `命中` int(11) NOT NULL DEFAULT 0 COMMENT '物理命中補正值',
  `傷害` int(11) NOT NULL DEFAULT 0 COMMENT '物理傷害補正值',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '敏捷外控：id=DEX值，命中=命中補正，傷害=傷害補正' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 角色_敏捷成長
-- ----------------------------

-- ----------------------------
-- Table structure for 角色_智力成長
-- ----------------------------
DROP TABLE IF EXISTS `角色_智力成長`;
CREATE TABLE `角色_智力成長`  (
  `id` int(11) NOT NULL COMMENT '智力值 (INT，1~127，等同流水排序)',
  `魔法加成` int(11) NOT NULL DEFAULT 0 COMMENT 'Magic Bonus 額外魔法點數',
  `治癒骰加成` int(11) NOT NULL DEFAULT 0 COMMENT '治癒術額外骰次（無程式上限，依智力外控）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '智力外控：id=INT值，魔法加成=Magic Bonus' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 角色_智力成長
-- ----------------------------

-- ----------------------------
-- Table structure for 角色_精神成長
-- ----------------------------
DROP TABLE IF EXISTS `角色_精神成長`;
CREATE TABLE `角色_精神成長`  (
  `id` int(11) NOT NULL COMMENT '精神值 (WIS，0~50，等同流水排序)',
  `mp_add` int(11) NOT NULL DEFAULT 0 COMMENT '精神固定加成(可負數)',
  `魔防` int(11) NOT NULL DEFAULT 0 COMMENT '精神追加抗魔值 (MR bonus)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '精神外控：id=WIS值，成長量=升級MP加成，魔防=MR加成' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 角色_精神成長
-- ----------------------------

-- ----------------------------
-- Table structure for 角色_體質成長
-- ----------------------------
DROP TABLE IF EXISTS `角色_體質成長`;
CREATE TABLE `角色_體質成長`  (
  `id` int(11) NOT NULL COMMENT '體質值 (CON，1~50，等同流水排序)',
  `hp_add` int(11) NOT NULL DEFAULT 0 COMMENT '體質固定加成(可負數)',
  `回血` int(11) NOT NULL DEFAULT 1 COMMENT '每 tick 自然回血隨機加成上限 (1~N)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '體質外控：id=CON值，成長量=升級HP加成，回血=HPR隨機上限' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 角色_體質成長
-- ----------------------------

-- ----------------------------
-- Table structure for 贊助_●●●●●●●
-- ----------------------------
DROP TABLE IF EXISTS `贊助_●●●●●●●`;
CREATE TABLE `贊助_●●●●●●●`  (
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 贊助_●●●●●●●
-- ----------------------------

-- ----------------------------
-- Table structure for 贊助_比值獎勵
-- ----------------------------
DROP TABLE IF EXISTS `贊助_比值獎勵`;
CREATE TABLE `贊助_比值獎勵`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `min` bigint(20) NOT NULL DEFAULT 0 COMMENT '金額區間下限(含，對應 count)',
  `max` bigint(20) NOT NULL DEFAULT 0 COMMENT '金額區間上限(含)',
  `比值` decimal(6, 1) NOT NULL DEFAULT 1.0 COMMENT '乘在 count 上；例 1.5 即 1000→1500',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '贊助主品數量比值（靜態）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 贊助_比值獎勵
-- ----------------------------

-- ----------------------------
-- Table structure for 贊助_滿額獎勵
-- ----------------------------
DROP TABLE IF EXISTS `贊助_滿額獎勵`;
CREATE TABLE `贊助_滿額獎勵`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `item_id` int(11) NOT NULL DEFAULT 0 COMMENT '額外獎勵道具編號',
  `名稱` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '顯示用名稱或備註',
  `數量` int(11) NOT NULL DEFAULT 1 COMMENT '額外發放數量',
  `滿額度` int(11) NOT NULL DEFAULT 0 COMMENT '與單筆贊助紀錄 count 全等比對，相符時觸發',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_滿額度`(`滿額度`) USING BTREE COMMENT '同一面額僅一筆加碼，避免重複定義'
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '贊助滿額額外獎勵（靜態）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 贊助_滿額獎勵
-- ----------------------------

-- ----------------------------
-- Table structure for 贊助_累計獎勵
-- ----------------------------
DROP TABLE IF EXISTS `贊助_累計獎勵`;
CREATE TABLE `贊助_累計獎勵`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `item_id` int(11) NOT NULL DEFAULT 0 COMMENT '獎勵道具編號',
  `名稱` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '顯示用名稱或備註',
  `累計ezpay額度` bigint(20) NOT NULL DEFAULT 0 COMMENT '帳號累積贊助門檻(accounts.ezpay)，本輪(舊,新]涵蓋此值時觸發',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_累計額度`(`累計ezpay額度`) USING BTREE COMMENT '同一累計門檻只保留一筆獎勵定義'
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '贊助累計門檻獎勵（靜態）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 贊助_累計獎勵
-- ----------------------------

-- ----------------------------
-- Table structure for 贊助_首儲獎勵
-- ----------------------------
DROP TABLE IF EXISTS `贊助_首儲獎勵`;
CREATE TABLE `贊助_首儲獎勵`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `item_id` int(11) NOT NULL DEFAULT 0 COMMENT '獎勵道具編號',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '顯示用名稱或備註',
  `首次贊助額度` bigint(20) NOT NULL DEFAULT 0 COMMENT '首充門檻(>=本筆領取額中「最小可套用」= ceilingEntry)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_首儲額度`(`首次贊助額度`) USING BTREE COMMENT '同一首儲門檻僅一筆'
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '贊助首儲（靜態，ezpay 由 0 之首次加值觸發一次）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 贊助_首儲獎勵
-- ----------------------------

