  `npc_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '怪物名稱(僅備註用)',
  `chance` int(10) NOT NULL DEFAULT 0 COMMENT '機率權重(總和建議1000000)',
  PRIMARY KEY (`npc_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

