DROP TABLE IF EXISTS `道具_物品強制給予`;
CREATE TABLE `道具_物品強制給予`  (
  `itemid` int(11) NOT NULL COMMENT '道具ID (需存在於 weapon/armor/etcitem)',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '說明:',
  `max` int(11) NULL DEFAULT 0 COMMENT '單次給予數量上限，0=不限制',
  PRIMARY KEY (`itemid`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '限制給予NPC道具：白名單，僅表單內道具可給予NPC' ROW_FORMAT = COMPACT;

