-- ----------------------------
-- Table structure for 道具_背包物品能力
-- ----------------------------
DROP TABLE IF EXISTS `道具_背包物品能力`;
CREATE TABLE `道具_背包物品能力`  (
  `item_id` int(11) NOT NULL COMMENT '道具ID',
  `add_str` int(11) NULL DEFAULT 0,
  `add_dex` int(11) NULL DEFAULT 0,
  `add_con` int(11) NULL DEFAULT 0,
  `add_int` int(11) NULL DEFAULT 0,
  `add_wis` int(11) NULL DEFAULT 0,
  `add_cha` int(11) NULL DEFAULT 0,
  `add_ac` int(11) NULL DEFAULT 0,
  `add_hp` int(11) NULL DEFAULT 0,
  `add_mp` int(11) NULL DEFAULT 0,
  `add_hpr` int(11) NULL DEFAULT 0,
  `add_mpr` int(11) NULL DEFAULT 0,
  `add_mr` int(11) NULL DEFAULT 0,
  `add_sp` int(11) NULL DEFAULT 0,
  `add_dmg` int(11) NULL DEFAULT 0,
  `add_bow_dmg` int(11) NULL DEFAULT 0,
  `add_hit` int(11) NULL DEFAULT 0,
  `add_bow_hit` int(11) NULL DEFAULT 0,
  `add_dmg_r` int(11) NULL DEFAULT 0,
  `add_magic_r` int(11) NULL DEFAULT 0,
  `add_fire` int(11) NULL DEFAULT 0,
  `add_wind` int(11) NULL DEFAULT 0,
  `add_earth` int(11) NULL DEFAULT 0,
  `add_water` int(11) NULL DEFAULT 0,
  `add_stun` int(11) NULL DEFAULT 0,
  `add_stone` int(11) NULL DEFAULT 0,
  `add_sleep` int(11) NULL DEFAULT 0,
  `add_freeze` int(11) NULL DEFAULT 0,
  `add_sustain` int(11) NULL DEFAULT 0,
  `add_blind` int(11) NULL DEFAULT 0,
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '背包能力道具：放入背包即附加能力' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 道具_背包物品能力
-- ----------------------------

-- ----------------------------
-- Table structure for 道具_自訂區域傳送
-- ----------------------------
DROP TABLE IF EXISTS `道具_自訂區域傳送`;
CREATE TABLE `道具_自訂區域傳送`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '規則編號',
  `道具id` int(10) UNSIGNED NOT NULL COMMENT 'etcitem.item_id',
  `道具名稱` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '管理說明，不參與判定',
  `限定使用地圖` smallint(6) NOT NULL DEFAULT -1 COMMENT '-1=不限來源地圖',
  `限定使用X1` int(11) NOT NULL DEFAULT 0 COMMENT '四個來源座標皆為0時不限區域；否則為矩形起點X',
  `限定使用Y1` int(11) NOT NULL DEFAULT 0 COMMENT '四個來源座標皆為0時不限區域；否則為矩形起點Y',
  `限定使用X2` int(11) NOT NULL DEFAULT 0 COMMENT '四個來源座標皆為0時不限區域；否則為矩形終點X',
  `限定使用Y2` int(11) NOT NULL DEFAULT 0 COMMENT '四個來源座標皆為0時不限區域；否則為矩形終點Y',
  `目標X` int(11) NOT NULL,
  `目標Y` int(11) NOT NULL,
  `目標隨機範圍` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '0=固定座標；N=目標周圍 N 格內可走位置',
  `目標地圖` smallint(5) UNSIGNED NOT NULL,
  `目標面向` tinyint(3) UNSIGNED NOT NULL DEFAULT 5 COMMENT '0~7',
  `備註` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_item_id`(`道具id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '一個道具對應一個來源區域與傳送目標' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 道具_自訂區域傳送
-- ----------------------------

-- ----------------------------
-- Table structure for 道具_自訂怪物召喚
-- ----------------------------
DROP TABLE IF EXISTS `道具_自訂怪物召喚`;
CREATE TABLE `道具_自訂怪物召喚`  (
  `item_id` int(10) NOT NULL COMMENT '道具編號',
  `note` varchar(70) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'NULL',
  `npc_id` int(10) NOT NULL COMMENT '召喚的怪物編號',
  `chance` int(10) NOT NULL DEFAULT 1 COMMENT '出現權重',
  `name` varchar(70) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'NULL',
  `限定地圖` int(11) NOT NULL DEFAULT -1 COMMENT '-1=不限',
  `限定X1` int(11) NOT NULL DEFAULT 0,
  `限定Y1` int(11) NOT NULL DEFAULT 0,
  `限定X2` int(11) NOT NULL DEFAULT 65535,
  `限定Y2` int(11) NOT NULL DEFAULT 65535,
  `存活秒數` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '0=永久',
  PRIMARY KEY (`item_id`, `npc_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '道具召喚設定表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 道具_自訂怪物召喚
-- ----------------------------

-- ----------------------------
-- Table structure for 道具_自訂溶解物品
-- ----------------------------
DROP TABLE IF EXISTS `道具_自訂溶解物品`;
CREATE TABLE `道具_自訂溶解物品`  (
  `resolvent_id` int(11) NOT NULL COMMENT '溶解劑Item ID (例如: 41245)',
  `target_item_id` int(11) NOT NULL COMMENT '被溶解的道具Item ID',
  `result_item_id` int(11) NOT NULL COMMENT '獲得的道具Item ID (例如: 40308金幣)',
  `min_count` int(11) NULL DEFAULT 1 COMMENT '最小獲得數量',
  `max_count` int(11) NULL DEFAULT 1 COMMENT '最大獲得數量',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '備註',
  PRIMARY KEY (`resolvent_id`, `target_item_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '溶解劑配方數據' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of 道具_自訂溶解物品
-- ----------------------------

-- ----------------------------
-- Table structure for 道具_自訂物品升級
-- ----------------------------
DROP TABLE IF EXISTS `道具_自訂物品升級`;
CREATE TABLE `道具_自訂物品升級`  (
  `itemid` int(10) NOT NULL DEFAULT 0 COMMENT '要升级的物品ITEMID',
  `nedid` int(10) NOT NULL DEFAULT 0 COMMENT '需要的强化卷编号',
  `type_id` int(10) NOT NULL DEFAULT 0 COMMENT '群组ID',
  `order_id` int(10) NOT NULL DEFAULT 0 COMMENT '群组排序',
  `mode` int(10) NOT NULL DEFAULT 0 COMMENT '0:无 1:强化失败会倒退 2:强化失败会消失',
  `random` int(10) NOT NULL DEFAULT 0 COMMENT '强化机率(1/1000)',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '说明',
  PRIMARY KEY (`itemid`, `type_id`, `order_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of 道具_自訂物品升級
-- ----------------------------

-- ----------------------------
-- Table structure for 道具_自訂穿脫能力
-- ----------------------------
DROP TABLE IF EXISTS `道具_自訂穿脫能力`;
CREATE TABLE `道具_自訂穿脫能力`  (
  `道具編號` int(11) NOT NULL COMMENT '對應 etcitem.item_id',
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '遊戲內顯示名稱',
  `類型` int(11) NULL DEFAULT 0 COMMENT '同類型互斥',
  `力量` int(11) NULL DEFAULT 0,
  `敏捷` int(11) NULL DEFAULT 0,
  `體質` int(11) NULL DEFAULT 0,
  `智力` int(11) NULL DEFAULT 0,
  `精神` int(11) NULL DEFAULT 0,
  `魅力` int(11) NULL DEFAULT 0,
  `防禦` int(11) NULL DEFAULT 0,
  `血量` int(11) NULL DEFAULT 0,
  `魔量` int(11) NULL DEFAULT 0,
  `回血` int(11) NULL DEFAULT 0,
  `回魔` int(11) NULL DEFAULT 0,
  `近戰傷害` int(11) NULL DEFAULT 0,
  `近戰命中` int(11) NULL DEFAULT 0,
  `遠攻傷害` int(11) NULL DEFAULT 0,
  `遠攻命中` int(11) NULL DEFAULT 0,
  `傷害減免` int(11) NULL DEFAULT 0,
  `魔法傷害減免` int(11) NULL DEFAULT 0,
  `抗魔` int(11) NULL DEFAULT 0,
  `魔攻` int(11) NULL DEFAULT 0,
  `火屬性防禦` int(11) NULL DEFAULT 0,
  `風屬性防禦` int(11) NULL DEFAULT 0,
  `地屬性防禦` int(11) NULL DEFAULT 0,
  `水屬性防禦` int(11) NULL DEFAULT 0,
  `昏迷耐性` int(11) NULL DEFAULT 0,
  `石化耐性` int(11) NULL DEFAULT 0,
  `睡眠耐性` int(11) NULL DEFAULT 0,
  `寒冰耐性` int(11) NULL DEFAULT 0,
  `支撐耐性` int(11) NULL DEFAULT 0,
  `暗黑耐性` int(11) NULL DEFAULT 0,
  `經驗獲取率` int(11) NULL DEFAULT 0 COMMENT '百分比',
  `金幣獲取率` int(11) NULL DEFAULT 0 COMMENT '百分比',
  `狀態圖編號` int(11) NULL DEFAULT 0 COMMENT 'effectlist2 effect id',
  `變身編號` int(11) NULL DEFAULT 0 COMMENT '穿上變身，脫下解除',
  PRIMARY KEY (`道具編號`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'VIP特殊可裝備道具：etcitem雙擊裝備' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 道具_自訂穿脫能力
-- ----------------------------

-- ----------------------------
-- Table structure for 道具_自訂配對合成
-- ----------------------------
DROP TABLE IF EXISTS `道具_自訂配對合成`;
CREATE TABLE `道具_自訂配對合成`  (
  `觸發道具編號` int(11) NOT NULL COMMENT '雙擊觸發（等同鑰匙），每次固定扣 1',
  `材料編號` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '材料 itemId，逗號分隔',
  `材料數量` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '對應數量，逗號分隔，須與材料編號欄位個數一致',
  `產物編號` int(11) NOT NULL COMMENT '成功產出 itemId',
  `產物數量` int(11) NOT NULL DEFAULT 1 COMMENT '產出數量',
  `備註` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '營運備註',
  PRIMARY KEY (`觸發道具編號`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '道具雙擊配對合成（觸發物+材料→產物）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 道具_自訂配對合成
-- ----------------------------

-- ----------------------------
-- Table structure for 道具_變形控制魔杖
-- ----------------------------
DROP TABLE IF EXISTS `道具_變形控制魔杖`;
CREATE TABLE `道具_變形控制魔杖`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `poly_id` int(10) NOT NULL DEFAULT 0 COMMENT '變身代碼(PolyID)',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '變身名稱(備註用)',
  `chance` int(10) NOT NULL DEFAULT 0 COMMENT '機率 (總合需為 1,000,000)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of 道具_變形控制魔杖
