-- Table structure for a_任務編號記錄
-- ----------------------------
DROP TABLE IF EXISTS `a_任務編號記錄`;
CREATE TABLE `a_任務編號記錄`  (
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `note1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of a_任務編號記錄
-- ----------------------------

-- ----------------------------
-- Table structure for armor
-- ----------------------------
DROP TABLE IF EXISTS `armor`;
CREATE TABLE `armor`  (
  `note` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '備註欄位（開發/管理用）',
  `item_id` int(5) NOT NULL AUTO_INCREMENT,
  `set_id` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '套裝編號 (支援多套裝, 逗號分隔)',
  `name` varchar(70) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'NULL',
  `classname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `name_id` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `type` varchar(15) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `material` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `weight` int(7) UNSIGNED NOT NULL DEFAULT 0,
  `invgfx` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `grdgfx` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `itemdesc_id` int(10) NOT NULL DEFAULT 0,
  `ac` int(3) NOT NULL DEFAULT 0,
  `safenchant` int(2) NOT NULL DEFAULT 0,
  `use_royal` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_knight` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_mage` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_elf` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_darkelf` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_dragonknight` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_illusionist` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `add_str` int(2) NOT NULL DEFAULT 0,
  `add_con` int(2) NOT NULL DEFAULT 0,
  `add_dex` int(2) NOT NULL DEFAULT 0,
  `add_int` int(2) NOT NULL DEFAULT 0,
  `add_wis` int(2) NOT NULL DEFAULT 0,
  `add_cha` int(2) NOT NULL DEFAULT 0,
  `add_hp` int(10) NOT NULL DEFAULT 0,
  `add_mp` int(10) NOT NULL DEFAULT 0,
  `add_hpr` int(10) NOT NULL DEFAULT 0,
  `add_mpr` int(10) NOT NULL DEFAULT 0,
  `add_sp` int(10) NOT NULL DEFAULT 0,
  `min_lvl` int(4) UNSIGNED NOT NULL DEFAULT 0,
  `max_lvl` int(4) UNSIGNED NOT NULL DEFAULT 0,
  `m_def` int(2) NOT NULL DEFAULT 0,
  `haste_item` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `damage_reduction` int(10) NOT NULL DEFAULT 0,
  `magicdmgmodifier` int(10) NOT NULL DEFAULT 0 COMMENT '魔法傷害加成',
  `add_melee_redux` int(10) NOT NULL DEFAULT 0 COMMENT '近距離傷害減免',
  `add_bow_redux` int(10) NOT NULL DEFAULT 0 COMMENT '遠距離傷害減免',
  `weight_reduction` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `hit_modifier` int(10) NOT NULL DEFAULT 0,
  `dmg_modifier` int(10) NOT NULL DEFAULT 0,
  `bow_hit_modifier` int(10) NOT NULL DEFAULT 0,
  `bow_dmg_modifier` int(10) NOT NULL DEFAULT 0,
  `bless` int(2) UNSIGNED NOT NULL DEFAULT 1,
  `trade` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `cant_delete` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `max_use_time` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `defense_water` int(2) NOT NULL DEFAULT 0,
  `defense_wind` int(2) NOT NULL DEFAULT 0,
  `defense_fire` int(2) NOT NULL DEFAULT 0,
  `defense_earth` int(2) NOT NULL DEFAULT 0,
  `regist_stun` int(2) NOT NULL DEFAULT 0,
  `regist_stone` int(2) NOT NULL DEFAULT 0,
  `regist_sleep` int(2) NOT NULL DEFAULT 0,
  `regist_freeze` int(2) NOT NULL DEFAULT 0,
  `regist_sustain` int(2) NOT NULL DEFAULT 0,
  `regist_blind` int(2) NOT NULL DEFAULT 0,
  `is_activity` int(2) NULL DEFAULT 0 COMMENT '是否為活動戒指或收費戒指',
  `add_pvp_redux` int(10) NOT NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `add_ignore_reduction` int(10) NOT NULL DEFAULT 0 COMMENT '無視傷害減免',
  `add_pvp_dmg` int(10) NOT NULL DEFAULT 0 COMMENT 'PVP追加傷害',
  `add_boss_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '對 BOSS 傷害加成',
  `add_boss_redux` int(11) NOT NULL DEFAULT 0 COMMENT '受到 BOSS 傷害減免%',
  `add_dodge` int(10) NOT NULL DEFAULT 0 COMMENT '閃避率',
  `add_er` int(10) NOT NULL DEFAULT 0 COMMENT 'ER迴避',
  `add_hitup` int(10) NOT NULL DEFAULT 0 COMMENT '近戰命中',
  `add_dmgup` int(10) NOT NULL DEFAULT 0 COMMENT '近戰傷害',
  `add_bow_hitup` int(10) NOT NULL DEFAULT 0 COMMENT '遠距命中',
  `add_bow_dmgup` int(10) NOT NULL DEFAULT 0 COMMENT '遠距傷害',
  `add_stun_success` int(10) NOT NULL DEFAULT 0 COMMENT '暈眩成功率',
  `add_potion_recovery` int(10) NOT NULL DEFAULT 0 COMMENT '藥水恢復量增加',
  `add_poison_resist` int(10) NOT NULL DEFAULT 0 COMMENT '毒性抵抗(0/1)',
  `add_adena_rate` int(10) NOT NULL DEFAULT 0 COMMENT '金幣獲取率(%)',
  `add_drop_rate` int(10) NOT NULL DEFAULT 0 COMMENT '掉寶獲取率(%)',
  `add_exp_rate` int(10) NOT NULL DEFAULT 0 COMMENT '經驗獲取率(%)',
  `add_magic_hit` int(10) NOT NULL DEFAULT 0 COMMENT '魔法命中率',
  `greater_tier` int(11) NULL DEFAULT 0 COMMENT '初始階級 (0:無, 1~5:階級)',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 332048 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of armor
-- ----------------------------

-- ----------------------------
-- Table structure for beginner
-- ----------------------------
DROP TABLE IF EXISTS `beginner`;
CREATE TABLE `beginner`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `item_id` int(6) NOT NULL DEFAULT 0,
  `count` int(10) NOT NULL DEFAULT 0,
  `enchantlvl` int(6) NOT NULL DEFAULT 0,
  `item_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `job_limit` tinyint(3) UNSIGNED NOT NULL DEFAULT 127 COMMENT '職業限制 127=全職 1王2騎4精8法16黑32龍64幻',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 19 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of beginner
-- ----------------------------

-- ----------------------------
-- Table structure for commands
-- ----------------------------
DROP TABLE IF EXISTS `commands`;
CREATE TABLE `commands`  (
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `access_level` int(10) NOT NULL DEFAULT 200,
  `class_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `system` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`name`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of commands
-- ----------------------------

-- ----------------------------
-- Table structure for droplist
-- ----------------------------
DROP TABLE IF EXISTS `droplist`;
CREATE TABLE `droplist`  (
  `mobId` int(6) UNSIGNED NOT NULL DEFAULT 0,
  `itemId` int(6) UNSIGNED NOT NULL DEFAULT 0,
  `min` int(4) UNSIGNED NOT NULL DEFAULT 0,
  `max` int(4) UNSIGNED NOT NULL DEFAULT 0,
  `chance` int(8) UNSIGNED NOT NULL DEFAULT 0,
  `note` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`mobId`, `itemId`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of droplist
-- ----------------------------

-- ----------------------------
-- Table structure for droplist_全怪掉落
-- ----------------------------
DROP TABLE IF EXISTS `droplist_全怪掉落`;
CREATE TABLE `droplist_全怪掉落`  (
  `itemid` int(11) NOT NULL COMMENT '道具編號',
  `min` int(11) NOT NULL DEFAULT 1 COMMENT '最少數量',
  `max` int(11) NOT NULL DEFAULT 1 COMMENT '最多數量',
  `chance` int(11) NOT NULL DEFAULT 0 COMMENT '百萬分率 1~1000000',
  `限制星期` int(11) NOT NULL DEFAULT -1 COMMENT '1~7；<=0不限制',
  `幾點開始` int(11) NOT NULL DEFAULT -1 COMMENT '0~23；<0不限制',
  `幾點結束` int(11) NOT NULL DEFAULT -1 COMMENT '0~23；<0不限制',
  `note` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '備註，啟動可自動補',
  PRIMARY KEY (`itemid`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '全怪物額外掉落（靜態配置）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of droplist_全怪掉落
-- ----------------------------

-- ----------------------------
-- Table structure for droplist_地圖掉落
-- ----------------------------
DROP TABLE IF EXISTS `droplist_地圖掉落`;
CREATE TABLE `droplist_地圖掉落`  (
  `mapid` int(11) NOT NULL COMMENT '地圖編號',
  `itemid` int(11) NOT NULL COMMENT '道具編號',
  `min` int(11) NOT NULL DEFAULT 1 COMMENT '最少數量',
  `max` int(11) NOT NULL DEFAULT 1 COMMENT '最多數量',
  `chance` int(11) NOT NULL DEFAULT 0 COMMENT '百萬分率 1~1000000',
  `note` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '備註',
  PRIMARY KEY (`mapid`, `itemid`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '指定地圖全怪掉落' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of droplist_地圖掉落
-- ----------------------------

-- ----------------------------
-- Table structure for dungeon
-- ----------------------------
DROP TABLE IF EXISTS `dungeon`;
CREATE TABLE `dungeon`  (
  `src_x` int(10) NOT NULL DEFAULT 0,
  `src_y` int(10) NOT NULL DEFAULT 0,
  `src_mapid` int(10) NOT NULL DEFAULT 0,
  `new_x` int(10) NULL DEFAULT 0,
  `new_y` int(10) NULL DEFAULT 0,
  `new_mapid` int(10) NULL DEFAULT 0,
  `new_heading` int(10) NULL DEFAULT 1,
  `note` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `require_item_id` int(10) NOT NULL DEFAULT 0 COMMENT '????ID?0=???',
  PRIMARY KEY (`src_x`, `src_y`, `src_mapid`, `require_item_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'MyISAM free: 8192 kB' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of dungeon
-- ----------------------------

-- ----------------------------
-- Table structure for dungeon_random
-- ----------------------------
DROP TABLE IF EXISTS `dungeon_random`;
CREATE TABLE `dungeon_random`  (
  `src_x` int(10) NOT NULL DEFAULT 0,
  `src_y` int(10) NOT NULL DEFAULT 0,
  `src_mapid` int(10) NOT NULL DEFAULT 0,
  `new_x1` int(10) NOT NULL DEFAULT 0,
  `new_y1` int(10) NOT NULL DEFAULT 0,
  `new_mapid1` int(10) NOT NULL DEFAULT 0,
  `new_x2` int(10) NOT NULL DEFAULT 0,
  `new_y2` int(10) NOT NULL DEFAULT 0,
  `new_mapid2` int(10) NOT NULL DEFAULT 0,
  `new_x3` int(10) NOT NULL DEFAULT 0,
  `new_y3` int(10) NOT NULL DEFAULT 0,
  `new_mapid3` int(10) NOT NULL DEFAULT 0,
  `new_x4` int(10) NOT NULL DEFAULT 0,
  `new_y4` int(10) NOT NULL DEFAULT 0,
  `new_mapid4` int(10) NOT NULL DEFAULT 0,
  `new_x5` int(10) NOT NULL DEFAULT 0,
  `new_y5` int(10) NOT NULL DEFAULT 0,
  `new_mapid5` int(10) NOT NULL DEFAULT 0,
  `new_heading` int(10) NOT NULL DEFAULT 1,
  `note` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`src_x`, `src_y`, `src_mapid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'MyISAM free: 8192 kB' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of dungeon_random
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem
-- ----------------------------
DROP TABLE IF EXISTS `etcitem`;
CREATE TABLE `etcitem`  (
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '企劃／維運備註（程式不讀取）',
  `item_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '道具編號（主鍵）',
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '遊戲內顯示名稱',
  `classname` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT 'ItemExecutor 類別；0=無自訂類別',
  `name_id` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '客戶端字串資源 ID',
  `item_type` varchar(40) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '大分類鍵字（須符合 ItemTable）',
  `use_type` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '使用類型鍵字（須符合 ItemTable._useTypes）',
  `material` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '材質鍵字（須符合 ItemTable._materialTypes）',
  `weight` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '重量',
  `invgfx` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '背包圖形 ID',
  `grdgfx` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '地面圖形 ID',
  `itemdesc_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '說明編號',
  `stackable` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '0=不可堆疊 1=可堆疊',
  `max_charge_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '充能／次數上限；0=不用',
  `min_lvl` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '最低等級；0=不限',
  `max_lvl` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '最高等級；0=不限',
  `bless` int(10) UNSIGNED NOT NULL DEFAULT 1 COMMENT '0一般 1祝福 2詛咒 3幻象（內部值）',
  `trade` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '1=不可交易',
  `cant_delete` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '1=不可刪除',
  `delay_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '共用冷卻群組 ID',
  `delay_time` int(10) NOT NULL DEFAULT 0 COMMENT '共用冷卻秒數（毫秒）',
  `delay_effect` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '道具使用延遲（毫秒）',
  `food_volume` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '食物相關數值',
  `save_at_once` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '1=狀態變更立即存檔',
  `limit_class` int(11) NOT NULL DEFAULT 127 COMMENT '職業位元遮罩；127=全職',
  PRIMARY KEY (`item_id`) USING BTREE,
  INDEX `item_id`(`item_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 561210 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of etcitem
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem_功能自訂
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_功能自訂`;
CREATE TABLE `etcitem_功能自訂`  (
  `item_id` int(11) NOT NULL COMMENT '道具編號（主鍵，對應 etcitem.item_id）',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '備註（企劃／除錯用）',
  `對象` tinyint(4) NOT NULL COMMENT '1=自己中心(無選目標，use_type 須為 normal 或 spell_1)；2=目標+座標(spell_long/spell_short/spell_long2)',
  `固定傷害` int(11) NOT NULL DEFAULT 0 COMMENT '傷害底值（與補血欄位二擇一，不可同時有傷害+補血）',
  `隨機傷害` int(11) NOT NULL DEFAULT 0 COMMENT '傷害額外隨機 0～N（含 N），實際傷害=固定傷害+隨機(0~N)',
  `固定補血` int(11) NOT NULL DEFAULT 0 COMMENT '補血底值（與傷害欄位二擇一）',
  `隨機補血` int(11) NOT NULL DEFAULT 0 COMMENT '補血額外隨機 0～N（含 N），實際補血=固定補血+隨機(0~N)',
  `範圍` int(11) NOT NULL DEFAULT 0 COMMENT '0=僅中心單體；>0=以中心為圓，周圍格數（getVisibleObjects 半徑）',
  `特效gfx` int(11) NOT NULL DEFAULT 0 COMMENT 'S_SkillSound 編號；0=不播放',
  `特效gfx2` int(11) NOT NULL DEFAULT 0 COMMENT '遠程飛行 S_UseAttackSkill；0=不播；>0須對象=2',
  `消耗道具` int(11) NOT NULL DEFAULT 0 COMMENT '額外消耗之道具 item_id；0=不扣額外道具',
  `道具數量` int(11) NOT NULL DEFAULT 0 COMMENT '額外消耗道具數量（消耗道具≠0 時須>0）',
  `消耗HP` int(11) NOT NULL DEFAULT 0 COMMENT '結算前自施法者扣除的 HP（須留足夠 HP，否則無法使用）',
  `消耗MP` int(11) NOT NULL DEFAULT 0 COMMENT '結算前自施法者扣除的 MP',
  `冰凍機率` int(11) NOT NULL DEFAULT 0 COMMENT '0-100，僅傷害模式、非自身；同命中與暈眩束縛擇一（暈眩>冰凍>束縛）',
  `冰凍秒數` int(11) NOT NULL DEFAULT 0 COMMENT '冰凍持續秒數，須>0 才與機率一併生效',
  `暈眩機率` int(11) NOT NULL DEFAULT 0 COMMENT '0-100',
  `暈眩秒數` int(11) NOT NULL DEFAULT 0 COMMENT '暈眩秒數（固定值，非 SHOCK_STUN 設定檔隨機）',
  `束縛機率` int(11) NOT NULL DEFAULT 0 COMMENT '0-100，大地束縛式',
  `束縛秒數` int(11) NOT NULL DEFAULT 0,
  `雙腳被困機率` int(11) NOT NULL DEFAULT 0 COMMENT '0-100，MOVE_STOP+TYPE_BIND，僅不可移動（非 isParalyzedX）',
  `雙腳被困秒數` int(11) NOT NULL DEFAULT 0 COMMENT '須>0 才與機率一併生效',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '通用自訂道具：由 EtcItemCustom 讀取；載入時會檢查對象與 use_type 是否相容' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of etcitem_功能自訂
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem_永久藥水
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_永久藥水`;
CREATE TABLE `etcitem_永久藥水`  (
  `item_id` int(11) NOT NULL COMMENT '道具ID',
  `max_count` int(11) NOT NULL DEFAULT 1 COMMENT '同一角色最大使用次數',
  `note` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '備註說明',
  `add_str` int(11) NOT NULL DEFAULT 0 COMMENT '力量',
  `add_dex` int(11) NOT NULL DEFAULT 0 COMMENT '敏捷',
  `add_con` int(11) NOT NULL DEFAULT 0 COMMENT '體質',
  `add_int` int(11) NOT NULL DEFAULT 0 COMMENT '智力',
  `add_wis` int(11) NOT NULL DEFAULT 0 COMMENT '精神',
  `add_cha` int(11) NOT NULL DEFAULT 0 COMMENT '魅力',
  `add_hp` int(11) NOT NULL DEFAULT 0 COMMENT 'HP上限',
  `add_mp` int(11) NOT NULL DEFAULT 0 COMMENT 'MP上限',
  `add_mr` int(11) NOT NULL DEFAULT 0 COMMENT '抗魔',
  `add_sp` int(11) NOT NULL DEFAULT 0 COMMENT '魔攻',
  `add_hit` int(11) NOT NULL DEFAULT 0 COMMENT '近距離命中',
  `add_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '近距離傷害',
  `add_bow_hit` int(11) NOT NULL DEFAULT 0 COMMENT '遠距離命中',
  `add_bow_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '遠距離傷害',
  `add_ac` int(11) NOT NULL DEFAULT 0 COMMENT '防禦力(負值=更好)',
  `add_dmg_redux` int(11) NOT NULL DEFAULT 0 COMMENT '傷害減免',
  `add_er` int(11) NOT NULL DEFAULT 0 COMMENT '迴避率',
  `add_def_fire` int(11) NOT NULL DEFAULT 0 COMMENT '火屬性防禦',
  `add_def_water` int(11) NOT NULL DEFAULT 0 COMMENT '水屬性防禦',
  `add_def_wind` int(11) NOT NULL DEFAULT 0 COMMENT '風屬性防禦',
  `add_def_earth` int(11) NOT NULL DEFAULT 0 COMMENT '地屬性防禦',
  `add_regist_freeze` int(11) NOT NULL DEFAULT 0 COMMENT '寒冰耐性',
  `add_regist_stone` int(11) NOT NULL DEFAULT 0 COMMENT '石化耐性',
  `add_regist_sleep` int(11) NOT NULL DEFAULT 0 COMMENT '睡眠耐性',
  `add_regist_blind` int(11) NOT NULL DEFAULT 0 COMMENT '暗黑耐性',
  `add_regist_stun` int(11) NOT NULL DEFAULT 0 COMMENT '昏迷耐性',
  `add_hp_regen` int(11) NOT NULL DEFAULT 0 COMMENT 'HP自然回復',
  `add_mp_regen` int(11) NOT NULL DEFAULT 0 COMMENT 'MP自然回復',
  `add_pvp_dmg` int(11) NOT NULL DEFAULT 0 COMMENT 'PVP傷害加成',
  `add_pvp_redux` int(11) NOT NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `add_boss_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '對 BOSS 傷害加成',
  `add_boss_redux` int(11) NOT NULL DEFAULT 0 COMMENT '受到 BOSS 傷害減免%',
  `add_exp_rate` int(11) NOT NULL DEFAULT 0 COMMENT '經驗獲取率(%)',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '永久能力設定表（道具）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of etcitem_永久藥水
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem_arrow
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_arrow`;
CREATE TABLE `etcitem_arrow`  (
  `item_id` int(10) UNSIGNED NOT NULL COMMENT '箭矢／飛刀道具編號（對應 etcitem.item_id）',
  `itemname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '道具名稱（管理辨識用）',
  `consume_on_attack` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '攻擊時是否消耗：0=不消耗 1=消耗',
  `dmg_small` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '對小型目標最大傷害',
  `dmg_large` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '對大型目標最大傷害',
  `arrow_spr` int(11) NOT NULL DEFAULT -1 COMMENT '飛行 GFX；-1=沿用武器／變身／原生預設',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of etcitem_arrow
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem_box
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_box`;
CREATE TABLE `etcitem_box`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `box_item_id` int(10) NOT NULL DEFAULT 0 COMMENT '物品编号',
  `get_item_id` int(10) NOT NULL,
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物品名称',
  `randomint` int(10) NOT NULL DEFAULT 1000000 COMMENT '比对用机率',
  `random` int(10) NOT NULL DEFAULT 1000 COMMENT '机率',
  `min_count` int(10) NOT NULL DEFAULT 1 COMMENT '给予数量(最少)',
  `max_count` int(10) NOT NULL DEFAULT 1 COMMENT '给予数量(最多)',
  `out` tinyint(1) NOT NULL DEFAULT 0 COMMENT '全服公告方式 0=不廣播 1=訊息欄 2=畫面中央 3=雙重',
  `全部發放` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '0=機率抽一筆；1=同寶箱標記1的列全部發放',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 501883 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of etcitem_box
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem_box寶箱自訂選擇
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_box寶箱自訂選擇`;
CREATE TABLE `etcitem_box寶箱自訂選擇`  (
  `寶箱編號` int(10) NOT NULL COMMENT '寶箱 ItemId',
  `獲得道具` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '可選物品ItemId (逗號分隔)',
  `道具強化值` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '對應強化值 (逗號分隔)',
  `道具數量` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '對應數量 (逗號分隔)',
  `bless` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '祝福狀態 (0:無 1:祝福 2:詛咒, 逗號分隔)',
  `out` int(10) NOT NULL DEFAULT 0 COMMENT '全服公告方式 0=不廣播 1=訊息欄 2=畫面中央 3=雙重',
  `說明` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '備註說明 (程式不讀取)',
  PRIMARY KEY (`寶箱編號`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of etcitem_box寶箱自訂選擇
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem_box_key
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_box_key`;
CREATE TABLE `etcitem_box_key`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `key_itemid` int(10) NOT NULL DEFAULT 0 COMMENT '需要使用的开启物件编号',
  `box_item_id` int(10) NOT NULL DEFAULT 0 COMMENT '物品编号',
  `get_item_id` int(10) NOT NULL,
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物品名称',
  `randomint` int(10) NOT NULL DEFAULT 1000000 COMMENT '比对用机率',
  `random` int(10) NOT NULL DEFAULT 1000 COMMENT '机率',
  `min_count` int(10) NOT NULL DEFAULT 1 COMMENT '给予数量(最少)',
  `max_count` int(10) NOT NULL DEFAULT 1 COMMENT '给予数量(最多)',
  `out` tinyint(1) NOT NULL DEFAULT 0 COMMENT '全服公告方式 0=不廣播 1=訊息欄 2=畫面中央 3=雙重',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1698 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

