-- ----------------------------
-- Table structure for etcitem_buff藥水能力
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_buff藥水能力`;
CREATE TABLE `etcitem_buff藥水能力`  (
  `item_id` int(10) NOT NULL COMMENT '道具ID',
  `note` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `str` int(10) NOT NULL DEFAULT 0,
  `dex` int(10) NOT NULL DEFAULT 0,
  `con` int(10) NOT NULL DEFAULT 0,
  `int` int(10) NOT NULL DEFAULT 0,
  `wis` int(10) NOT NULL DEFAULT 0,
  `cha` int(10) NOT NULL DEFAULT 0,
  `hp` int(10) NOT NULL DEFAULT 0,
  `mp` int(10) NOT NULL DEFAULT 0,
  `hpr` int(10) NOT NULL DEFAULT 0,
  `mpr` int(10) NOT NULL DEFAULT 0,
  `dmg` int(10) NOT NULL DEFAULT 0 COMMENT '近戰額外傷害',
  `hit` int(10) NOT NULL DEFAULT 0 COMMENT '近戰命中',
  `bow_dmg` int(10) NOT NULL DEFAULT 0 COMMENT '遠攻額外傷害',
  `bow_hit` int(10) NOT NULL DEFAULT 0 COMMENT '遠攻命中',
  `sp` int(10) NOT NULL DEFAULT 0 COMMENT '魔攻',
  `magic_hit` int(10) NOT NULL DEFAULT 0 COMMENT '魔法命中',
  `ac` int(10) NOT NULL DEFAULT 0 COMMENT '防禦 (負數為佳)',
  `mr` int(10) NOT NULL DEFAULT 0 COMMENT '魔防',
  `dmg_redux` int(10) NOT NULL DEFAULT 0 COMMENT '傷害減免',
  `er` int(10) NOT NULL DEFAULT 0 COMMENT '遠避 (ER)',
  `exp_rate` int(10) NOT NULL DEFAULT 0 COMMENT '經驗加成百分比 (如 150 = +150%)',
  `regist_stone` int(10) NOT NULL DEFAULT 0 COMMENT '石化耐性',
  `regist_sleep` int(10) NOT NULL DEFAULT 0 COMMENT '睡眠耐性',
  `regist_freeze` int(10) NOT NULL DEFAULT 0 COMMENT '寒冰耐性',
  `regist_stun` int(10) NOT NULL DEFAULT 0 COMMENT '昏迷耐性',
  `regist_blind` int(10) NOT NULL DEFAULT 0 COMMENT '暗黑耐性',
  `regist_poison` int(10) NOT NULL DEFAULT 0 COMMENT '抗毒 (大於0即免疫)',
  `dodge` int(10) NOT NULL DEFAULT 0 COMMENT '閃避率 (1=10%)',
  `regist_sustain` int(10) NOT NULL DEFAULT 0 COMMENT '支撐耐性',
  `resist_fire` int(10) NOT NULL DEFAULT 0,
  `resist_water` int(10) NOT NULL DEFAULT 0,
  `resist_wind` int(10) NOT NULL DEFAULT 0,
  `resist_earth` int(10) NOT NULL DEFAULT 0,
  `adena_rate` int(10) NOT NULL DEFAULT 0 COMMENT '金幣獲取率(%)',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '道具Buff屬性加成表 (水平寬表)' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of etcitem_buff藥水能力
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem_buff藥水設置
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_buff藥水設置`;
CREATE TABLE `etcitem_buff藥水設置`  (
  `item_id` int(10) NOT NULL COMMENT '道具ID',
  `note` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `use_custom_packet` tinyint(1) NOT NULL DEFAULT 0 COMMENT '自訂封包開關',
  `start_msg_str` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '自訂開始訊息',
  `end_msg_str` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '結束訊息字串',
  `buff_id` int(10) NOT NULL DEFAULT 0 COMMENT '虛擬狀態ID',
  `buff_time_sec` int(10) NOT NULL DEFAULT 0 COMMENT '時間(秒)',
  `cast_gfx` int(10) NOT NULL DEFAULT 0 COMMENT '施法動畫',
  `status_icon` int(10) NOT NULL DEFAULT 0 COMMENT '狀態圖示',
  `start_msg_id` int(10) NOT NULL DEFAULT 0 COMMENT '開始訊息ID',
  `consume_item_id` int(10) NOT NULL DEFAULT 0 COMMENT '消耗觸媒',
  `consume_count` int(10) NOT NULL DEFAULT 0 COMMENT '消耗數量',
  `group_check` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '互斥群組',
  `can_overwrite` tinyint(1) NOT NULL DEFAULT 0 COMMENT '遇到同群組時: 0=阻擋不消耗, 1=刪除舊狀態並覆蓋',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of etcitem_buff藥水設置
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem_doll_power_new
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_doll_power_new`;
CREATE TABLE `etcitem_doll_power_new`  (
  `id` int(11) NOT NULL COMMENT '編號',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '備註說明',
  `classname` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '能力代號 (對應 ItemAbility 或 ProcType)',
  `value_main` int(11) NOT NULL DEFAULT 0 COMMENT '主要數值 (屬性值/技能ID/道具ID)',
  `probability` int(11) NOT NULL DEFAULT 0 COMMENT '機率 1/1000 (僅主動觸發有效)',
  `interval_time` int(11) NOT NULL DEFAULT 0 COMMENT '時間間隔秒數 (僅定時能力有效)',
  `passive_skill_id` int(11) NOT NULL DEFAULT 0 COMMENT '常駐技能ID (自動施法用)',
  `mode` int(11) NOT NULL DEFAULT 0 COMMENT '模式: 1=傷害, 2=減傷, 3=恢復',
  `attr_type` int(11) NOT NULL DEFAULT 0 COMMENT '屬性: 0=無, 1=地, 2=火, 4=水, 8=風',
  `gfx_id` int(11) NOT NULL DEFAULT 0 COMMENT '特效ID',
  `gfx_target` int(11) NOT NULL DEFAULT 0 COMMENT '特效對象: 0=自身, 1=目標',
  `value_sub` int(11) NOT NULL DEFAULT 0 COMMENT '次要數值 (傷害值/道具數量/百分比)',
  `trigger_skill_id` int(11) NOT NULL DEFAULT 0 COMMENT '觸發技能ID (機率發動用)',
  `item_id` int(11) NOT NULL DEFAULT 0 COMMENT '給予道具ID',
  `item_count` int(11) NOT NULL DEFAULT 0 COMMENT '給予道具數量',
  `status_id` int(11) NOT NULL DEFAULT 0 COMMENT '特殊狀態ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of etcitem_doll_power_new
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem_doll_type
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_doll_type`;
CREATE TABLE `etcitem_doll_type`  (
  `itemid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '对应的物品编号',
  `doll_type` int(11) NOT NULL DEFAULT 0,
  `icon` int(11) NOT NULL DEFAULT 0,
  `note` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '中文注解',
  `powers` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '能力阵列',
  `add_power` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '可覺醒的能力ID池(逗號分隔)',
  `need` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '耗材编号阵列',
  `count` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '耗材数量阵列',
  `time` int(10) UNSIGNED NOT NULL DEFAULT 1800 COMMENT '可召唤时间(秒)',
  `gfxid` int(10) NOT NULL DEFAULT 0 COMMENT '外型代号',
  `nameid` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '$',
  PRIMARY KEY (`itemid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of etcitem_doll_type
-- ----------------------------

-- ----------------------------
-- Table structure for etcitem_teleport
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_teleport`;
CREATE TABLE `etcitem_teleport`  (
  `item_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `locx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `locy` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `mapid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`item_id`) USING BTREE,
  INDEX `item_id`(`item_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 5000561 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of etcitem_teleport
-- ----------------------------

-- ----------------------------
-- Table structure for exp
-- ----------------------------
DROP TABLE IF EXISTS `exp`;
CREATE TABLE `exp`  (
  `level` int(10) NOT NULL,
  `exp` bigint(11) UNSIGNED NOT NULL DEFAULT 0,
  `expPenalty` double(10, 2) NOT NULL DEFAULT 1.00,
  `death_penalty_rate` decimal(4, 2) NOT NULL DEFAULT 0.05 COMMENT '死亡損失經驗比例 0.05=5%',
  `restore_rate` decimal(4, 2) NOT NULL DEFAULT 0.03 COMMENT '恢復經驗比例 0.05=5%',
  `restore_cost` int(11) NOT NULL DEFAULT 0 COMMENT '恢復經驗值所需金幣',
  `talent_point` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '該等級對天賦配額之貢獻',
  PRIMARY KEY (`level`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = FIXED;

-- ----------------------------
-- Records of exp
-- ----------------------------

-- ----------------------------
-- Table structure for getback
-- ----------------------------
DROP TABLE IF EXISTS `getback`;
CREATE TABLE `getback`  (
  `area_x1` int(10) NOT NULL DEFAULT 0,
  `area_y1` int(10) NOT NULL DEFAULT 0,
  `area_x2` int(10) NOT NULL DEFAULT 0,
  `area_y2` int(10) NOT NULL DEFAULT 0,
  `area_mapid` int(10) NOT NULL DEFAULT 0,
  `getback_x1` int(10) NOT NULL DEFAULT 0,
  `getback_y1` int(10) NOT NULL DEFAULT 0,
  `getback_x2` int(10) NOT NULL DEFAULT 0,
  `getback_y2` int(10) NOT NULL DEFAULT 0,
  `getback_x3` int(10) NOT NULL DEFAULT 0,
  `getback_y3` int(10) NOT NULL DEFAULT 0,
  `getback_mapid` int(10) NOT NULL DEFAULT 0,
  `getback_townid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `getback_townid_elf` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `getback_townid_darkelf` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `scrollescape` int(10) NOT NULL DEFAULT 1,
  `note` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`area_x1`, `area_y1`, `area_x2`, `area_y2`, `area_mapid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of getback
-- ----------------------------

-- ----------------------------
-- Table structure for getback_restart
-- ----------------------------
DROP TABLE IF EXISTS `getback_restart`;
CREATE TABLE `getback_restart`  (
  `area` int(10) NOT NULL DEFAULT 0,
  `note` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `locx` int(10) NOT NULL DEFAULT 0,
  `locy` int(10) NOT NULL DEFAULT 0,
  `mapid` int(10) NOT NULL DEFAULT 0,
  PRIMARY KEY (`area`) USING BTREE
