-- Records of getback_restart
-- ----------------------------

-- ----------------------------
-- Table structure for mapids
-- ----------------------------
DROP TABLE IF EXISTS `mapids`;
CREATE TABLE `mapids`  (
  `mapid` int(10) NOT NULL DEFAULT 0 COMMENT '地圖編號（主鍵；伺服器與資料邏輯用的 mapId）',
  `locationname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '地名稱（顯示或後台辨識用）',
  `startX` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '可使用區域 X 座標下限（含）',
  `endX` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '可使用區域 X 座標上限（含）',
  `startY` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '可使用區域 Y 座標下限（含）',
  `endY` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '可使用區域 Y 座標上限（含）',
  `monster_amount` float UNSIGNED NOT NULL DEFAULT 0 COMMENT '該地圖怪物數量倍率（相對係數）',
  `drop_rate` float UNSIGNED NOT NULL DEFAULT 0 COMMENT '該地圖掉落倍率（相對係數）',
  `underwater` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否為水中地圖：1=是，0=否',
  `markable` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可記憶座標／書籤：1=可，0=不可',
  `teleportable` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否允許傳送類技能／道具：1=可，0=不可',
  `escapable` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否允許回捲／脫逃類：1=可，0=不可',
  `resurrection` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否允許復活：1=可，0=不可',
  `painwand` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否允許使用指定魔杖／返回類（依專案定義）：1=可，0=不可',
  `penalty` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否啟用死亡懲罰：1=有，0=無',
  `take_pets` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可攜帶寵物／追隨單位：1=可，0=不可',
  `recall_pets` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可召喚寵物／追隨單位：1=可，0=不可',
  `usable_item` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可使用一般道具：1=可，0=不可',
  `usable_skill` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可使用技能：1=可，0=不可',
  `is_guaji` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否允許內掛／掛機相關行為：1=允許，0=禁止',
  `usable_shop` int(10) NULL DEFAULT 0 COMMENT '是否允許擺攤／商店區：依專案與客戶端 shop 設定；常見 1=開、0=關',
  `is_arrows` tinyint(1) NOT NULL DEFAULT 0 COMMENT '穿雲招集等箭矢召集類：1=開，0=關',
  `CopyMapId` int(11) NOT NULL DEFAULT -1 COMMENT '複製母圖編號：障礙資料讀取 maps/{CopyMapId}.txt。預設 -1 = 不啟用；大於 0 啟用時須與母圖邊界完全一致',
  PRIMARY KEY (`mapid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of mapids
-- ----------------------------

-- ----------------------------
-- Table structure for mapids_恢復區域
-- ----------------------------
DROP TABLE IF EXISTS `mapids_恢復區域`;
CREATE TABLE `mapids_恢復區域`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `map_id` int(11) NOT NULL COMMENT '地圖 ID，-1 代表盟屋/內城通用',
  `min_x` int(11) NOT NULL DEFAULT 0 COMMENT '區域最小 X，0 表示不限',
  `min_y` int(11) NOT NULL DEFAULT 0 COMMENT '區域最小 Y，0 表示不限',
  `max_x` int(11) NOT NULL DEFAULT 0 COMMENT '區域最大 X，0 表示不限',
  `max_y` int(11) NOT NULL DEFAULT 0 COMMENT '區域最大 Y，0 表示不限',
  `hp_regen` int(11) NOT NULL DEFAULT 0 COMMENT 'HP 恢復加乘',
  `mp_regen` int(11) NOT NULL DEFAULT 0 COMMENT 'MP 恢復加乘',
  `interval_sec` int(11) NOT NULL DEFAULT 0 COMMENT '\'恢復間隔（秒），0 表示系統預設 64 秒\'',
  `disable_natural_mp` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1=該地圖禁用人物自然回魔',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '備註',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_map_id`(`map_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 156 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '地圖回血/回魔設定' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of mapids_恢復區域
-- ----------------------------

-- ----------------------------
-- Table structure for mapids_跨地形攻擊
-- ----------------------------
DROP TABLE IF EXISTS `mapids_跨地形攻擊`;
CREATE TABLE `mapids_跨地形攻擊`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `map_id` int(11) NOT NULL COMMENT '地圖編號',
  `min_x` int(11) NOT NULL COMMENT '矩形左上角 X（含）',
  `min_y` int(11) NOT NULL COMMENT '矩形左上角 Y（含）',
  `max_x` int(11) NOT NULL COMMENT '矩形右下角 X（含）',
  `max_y` int(11) NOT NULL COMMENT '矩形右下角 Y（含）',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '備註',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_map_arrow_passable_map`(`map_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '遠程／魔法視線可穿透障礙之區域（伺服器平行圖層）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of mapids_跨地形攻擊
-- ----------------------------

-- ----------------------------
-- Table structure for mapids_exp
-- ----------------------------
DROP TABLE IF EXISTS `mapids_exp`;
CREATE TABLE `mapids_exp`  (
  `mapid` int(10) NOT NULL DEFAULT 0,
  `locationname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `exp` double(10, 2) UNSIGNED NOT NULL DEFAULT 1.00,
  `min` int(10) NOT NULL DEFAULT 1,
  `max` int(10) NOT NULL DEFAULT 1,
  PRIMARY KEY (`mapid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of mapids_exp
-- ----------------------------

-- ----------------------------
-- Table structure for mapids_group
-- ----------------------------
DROP TABLE IF EXISTS `mapids_group`;
CREATE TABLE `mapids_group`  (
  `order_id` int(10) NOT NULL DEFAULT 0,
  `mapids` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `note` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `time` int(10) NOT NULL DEFAULT 158,
  `out_x` int(10) NOT NULL DEFAULT 0,
  `out_y` int(10) NOT NULL DEFAULT 0,
  `out_map` int(10) NOT NULL DEFAULT 0,
  PRIMARY KEY (`order_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of mapids_group
-- ----------------------------

-- ----------------------------
-- Table structure for mapids_level
-- ----------------------------
DROP TABLE IF EXISTS `mapids_level`;
CREATE TABLE `mapids_level`  (
  `mapid` int(10) NOT NULL DEFAULT 0,
  `locationname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `min` int(10) NOT NULL DEFAULT 0,
  `max` int(10) NOT NULL DEFAULT 158,
  `locx` int(10) NOT NULL DEFAULT 0,
  `locy` int(10) NOT NULL DEFAULT 0,
  `tomapid` int(10) NOT NULL DEFAULT 0,
  `note` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`mapid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of mapids_level
-- ----------------------------

-- ----------------------------
-- Table structure for mapids_shop
-- ----------------------------
DROP TABLE IF EXISTS `mapids_shop`;
CREATE TABLE `mapids_shop`  (
  `id` int(5) NOT NULL AUTO_INCREMENT COMMENT '流水號',
  `mapid` int(10) NOT NULL COMMENT '地圖編號',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '注解',
  `x_min` int(10) NOT NULL DEFAULT 0 COMMENT '區域起點X',
  `y_min` int(10) NOT NULL DEFAULT 0 COMMENT '區域起點Y',
  `x_max` int(10) NOT NULL DEFAULT 0 COMMENT '區域終點X',
  `y_max` int(10) NOT NULL DEFAULT 0 COMMENT '區域終點Y',
  `currency` int(10) NOT NULL DEFAULT 40308 COMMENT '交易貨幣道具ID（40308=金幣）',
  PRIMARY KEY (`id`, `mapid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of mapids_shop
-- ----------------------------

-- ----------------------------
-- Table structure for mapids_tile
-- ----------------------------
DROP TABLE IF EXISTS `mapids_tile`;
CREATE TABLE `mapids_tile`  (
  `map_id` int(11) NOT NULL COMMENT '地圖編號',
  `x` int(11) NOT NULL COMMENT '格座標 X',
  `y` int(11) NOT NULL COMMENT '格座標 Y',
  `tile` int(11) NOT NULL COMMENT '覆寫後的 tile 值（可走/障礙等，與伺服端地圖邏輯一致）',
  PRIMARY KEY (`map_id`, `x`, `y`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '地圖格覆寫（GM/工具寫入，開機由 MapTileTable 載入並套回記憶體地圖）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of mapids_tile
-- ----------------------------

-- ----------------------------
-- Table structure for mobgroup
-- ----------------------------
DROP TABLE IF EXISTS `mobgroup`;
CREATE TABLE `mobgroup`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `remove_group_if_leader_die` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `leader_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion1_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion1_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion2_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion2_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion3_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion3_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion4_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion4_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion5_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion5_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion6_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion6_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion7_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `minion7_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 75 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of mobgroup
-- ----------------------------

-- ----------------------------
-- Table structure for mobskill
-- ----------------------------
DROP TABLE IF EXISTS `mobskill`;
CREATE TABLE `mobskill`  (
  `mobid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `actNo` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `mobname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `Type` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `TriRnd` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `TriHp` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `TriCompanionHp` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `TriRange` int(10) NOT NULL DEFAULT 0,
  `TriCount` int(10) NOT NULL DEFAULT 0,
  `ChangeTarget` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Range` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `AreaWidth` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `AreaHeight` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Leverage` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `SkillId` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Gfxid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `ActId` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `SummonId` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `SummonMin` int(10) NOT NULL DEFAULT 0,
  `SummonMax` int(10) NOT NULL DEFAULT 0,
  `PolyId` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `reuseDelay` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '怪物技能再次使用延遲(毫秒);0=不限制',
  PRIMARY KEY (`mobid`, `actNo`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of mobskill
-- ----------------------------

-- ----------------------------
-- Table structure for npc
-- ----------------------------
DROP TABLE IF EXISTS `npc`;
CREATE TABLE `npc`  (
  `npcid` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'NPC 編號（主鍵）',
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'NPC 內部名稱（開發用）',
  `nameid` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'NPC 顯示名稱（$ 開頭為多語系代碼）',
  `classname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT 'NpcExecutor 類別名稱（0=無，如 mob.xxx）',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `impl` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '實例類別（如 L1Monster、L1PcInstance）',
  `gfxid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '圖形 ID（外觀編號）',
  `lvl` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '等級',
  `hp` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '生命值',
  `mp` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '魔力值',
  `ac` int(10) NOT NULL DEFAULT 0 COMMENT '防禦力（負值=較高防禦）',
  `str` int(10) NOT NULL DEFAULT 0 COMMENT '力量',
  `con` int(10) NOT NULL DEFAULT 0 COMMENT '體質',
  `dex` int(10) NOT NULL DEFAULT 0 COMMENT '敏捷',
  `wis` int(10) NOT NULL DEFAULT 0 COMMENT '智慧',
  `intel` int(10) NOT NULL DEFAULT 0 COMMENT '智力',
  `mr` int(10) NOT NULL DEFAULT 0 COMMENT '魔法抗性',
  `exp` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '經驗值',
  `lawful` int(10) NOT NULL DEFAULT 0 COMMENT '正義值',
  `size` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '體型（small/large）',
  `weakAttr` int(10) NOT NULL DEFAULT 0 COMMENT '弱點屬性（屬性相剋）',
  `ranged` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '遠距攻擊類型（0=近戰，1+=遠距）',
  `tamable` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可迷媚（0=否，1=是）',
  `passispeed` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '移動速度',
  `atkspeed` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '物理攻擊速度',
  `atk_magic_speed` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '魔法攻擊速度',
  `sub_magic_speed` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '魔法施放速度',
  `undead` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '不死系（0=否，1=是，2=變形怪）',
  `poison_atk` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '毒攻擊類型',
  `paralysis_atk` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '麻痺攻擊類型',
  `agro` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '主動攻擊（0=被動，1=主動）',
  `agrososc` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '受魔法攻擊時主動反擊',
  `agrocoi` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '受物理攻擊時主動反擊',
  `family` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '種族家族（如 daemon、skeleton）',
  `agrofamily` int(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '對同家族主動攻擊（0=否，1=是）',
  `agrogfxid1` int(10) NOT NULL DEFAULT -1 COMMENT '主動攻擊目標圖形 ID 1',
  `agrogfxid2` int(10) NOT NULL DEFAULT -1 COMMENT '主動攻擊目標圖形 ID 2',
  `picupitem` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否撿取道具',
  `digestitem` int(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '消化道具類型（0=不消化）',
  `bravespeed` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '勇敢加速（受傷時加速）',
  `hprinterval` int(6) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'HP 恢復間隔（毫秒，0=不恢復）',
  `hpr` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'HP 恢復量',
  `mprinterval` int(6) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'MP 恢復間隔（毫秒，0=不恢復）',
  `mpr` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'MP 恢復量',
  `teleport` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否會瞬移',
  `randomlevel` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '隨機等級範圍',
  `randomhp` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '隨機 HP 範圍',
  `randommp` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '隨機 MP 範圍',
  `randomac` int(3) NOT NULL DEFAULT 0 COMMENT '隨機 AC 範圍',
  `randomexp` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '隨機經驗值範圍',
  `randomlawful` int(5) NOT NULL DEFAULT 0 COMMENT '隨機正義值範圍',
  `damage_reduction` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '傷害減免',
  `hard` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '硬皮（物理傷害減半）',
  `doppel` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '變形怪（1=是）',
  `IsTU` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否受聖光術（ターンアンデッド）影響',
  `IsErase` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否受消除魔法（レースイマジック）影響',
  `bowActId` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '弓攻擊動作 ID',
  `karma` int(10) NOT NULL DEFAULT 0 COMMENT 'NPC 死亡時給予玩家的友好度',
  `transform_id` int(10) NOT NULL DEFAULT -1 COMMENT '變身目標 NPC ID（-1=無）',
  `transform_gfxid` int(10) NOT NULL DEFAULT 0 COMMENT '變身目標圖形 ID',
  `light_size` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '光照範圍',
  `amount_fixed` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '掉落數量固定（0=隨機，1=固定）',
  `change_head` int(1) NOT NULL DEFAULT 0 COMMENT '是否更換頭部外觀',
  `cant_resurrect` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '不可復活（0=可，1=不可）',
  `boss` int(1) NOT NULL DEFAULT 0 COMMENT '是否為 Boss（0=一般怪，1=Boss）',
  PRIMARY KEY (`npcid`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 297014 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of npc
-- ----------------------------

-- ----------------------------
-- Table structure for npc_擊殺獎勵
-- ----------------------------
DROP TABLE IF EXISTS `npc_擊殺獎勵`;
CREATE TABLE `npc_擊殺獎勵`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '流水號主鍵',
  `mob_id` int(11) NOT NULL COMMENT '觸發的怪物模板 npc_id（比對 L1MonsterInstance 之 getNpcId）',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '顯示／備註用名稱（發信來源等）',
  `最低傷害` int(11) NOT NULL DEFAULT 0 COMMENT '0=不檢查；大於0時，玩家累積傷害須大於等於此值才符合領取資格',
  `參與獎勵` int(11) NOT NULL DEFAULT 0 COMMENT '參與獎之道具 id；0=不發放',
  `尾刀獎勵` int(11) NOT NULL DEFAULT 0 COMMENT '最後一擊獎之道具 id；0=不發放',
  `傷害最高獎勵` int(11) NOT NULL DEFAULT 0 COMMENT '同場內合計傷害最高者之道具 id；0=不發放',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mob_id`(`mob_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'NPC 死亡寶物分配：畫面內可領、每人單一獎（傷害高>尾刀>參與）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of npc_擊殺獎勵
-- ----------------------------

-- ----------------------------
-- Table structure for npc_死亡傳送
-- ----------------------------
DROP TABLE IF EXISTS `npc_死亡傳送`;
CREATE TABLE `npc_死亡傳送`  (
  `npc_id` int(11) NOT NULL COMMENT '觸發的 NPC 編號（怪物死亡時比對此欄，主鍵）',
  `location` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '地點名稱 (備註用)',
  `locx` int(11) NOT NULL COMMENT '傳送目標 X 座標',
  `locy` int(11) NOT NULL COMMENT '傳送目標 Y 座標',
  `mapid` int(11) NOT NULL COMMENT '傳送目標地圖編號',
  `delay_sec` int(11) NOT NULL DEFAULT 3 COMMENT '死亡後延遲幾秒才傳送（0 為立即）',
  `effect_id` int(11) NOT NULL DEFAULT 169 COMMENT '傳送前額外特效編號（S_SkillSound；0 或負值表示不額外播放）',
  PRIMARY KEY (`npc_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'NPC 死亡全畫面玩家傳送設定' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of npc_死亡傳送
-- ----------------------------

-- ----------------------------
-- Table structure for npc_死亡召喚
-- ----------------------------
DROP TABLE IF EXISTS `npc_死亡召喚`;
CREATE TABLE `npc_死亡召喚`  (
  `npcid` int(10) NOT NULL COMMENT '怪物 NPC 編號 (死亡時觸發)',
  `chance` int(3) NOT NULL DEFAULT 100 COMMENT '觸發機率 1-100',
  `changeto` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '招喚目標 NPC ID，多個以逗號分隔隨機選一',
  `note` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '備註(程式不讀取)',
  PRIMARY KEY (`npcid`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '怪物死亡時依機率變身為其他怪物' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of npc_死亡召喚
-- ----------------------------

-- ----------------------------
-- Table structure for npc_自訂合成
-- ----------------------------
DROP TABLE IF EXISTS `npc_自訂合成`;
CREATE TABLE `npc_自訂合成`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `說明` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '備註說明 (程式不讀取)',
  `npcid` int(11) NOT NULL,
  `action` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `合成需求編號` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '40308',
  `物品合成數量` int(11) NOT NULL DEFAULT 1,
  `機率` int(11) NOT NULL DEFAULT 10,
  `獲取合成編號` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '40308',
  `物品不足Msg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `失敗Msg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `成功Msg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `世界廣播` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `廣播開關` int(11) NOT NULL DEFAULT 0 COMMENT '0=不廣播, 1=訊息欄, 2=畫面中央, 3=雙重',
  `spr跑圖欄位` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `特效抽獎欄位` int(11) NOT NULL DEFAULT 0 COMMENT '畫面特效 ID\r\n1;閃爍紫色邊框/2:畫面震動/3:放煙火/4:打雷變暗/5:飽食度閃爍/6:藍色邊框閃爍/7:火焰邊框閃爍/8:白色邊框閃爍',
  `動畫延遲毫秒` int(11) NOT NULL DEFAULT 2000,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 14 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of npc_自訂合成
-- ----------------------------

-- ----------------------------
-- Table structure for npc_action_making
-- ----------------------------
DROP TABLE IF EXISTS `npc_action_making`;
CREATE TABLE `npc_action_making`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `npc_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'NPC 編號，支援逗號分隔多組 (例: 70005,70506,70520)',
  `action_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Action 名稱',
  `amount_inputable` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否可輸入數量 (0:否, 1:是)',
  `materials` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '材料道具ID (逗號分隔)',
  `materials_count` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '材料數量 (逗號分隔)',
  `materials_enchant` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '材料強化要求 (-1=不檢查, 0=須+0, >0=須>=)',
  `results` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '產出道具ID (逗號分隔)',
  `results_count` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '產出數量 (逗號分隔)',
  `results_enchant` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '產出強化值 (逗號分隔)',
  `success_rate` int(11) NOT NULL DEFAULT 1000 COMMENT '成功率 (千分比: 0-1000)',
  `fail_item_id` int(11) NOT NULL DEFAULT 0 COMMENT '失敗產出物品 ID (0 表示無)',
  `min_level` int(11) NOT NULL DEFAULT 0 COMMENT '最低等級限制',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '備註',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_npc_action`(`npc_id`, `action_name`) USING BTREE,
  INDEX `idx_action_name`(`action_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1255 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'NPC 製作系統配置' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of npc_action_making
-- ----------------------------

-- ----------------------------
-- Table structure for npc_action_teleport
-- ----------------------------
DROP TABLE IF EXISTS `npc_action_teleport`;
CREATE TABLE `npc_action_teleport`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主鍵 ID',
  `npc_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'NPC 編號，支援逗號分隔多組 (例: 50020,50024,50025)',
  `action_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Action 名稱',
  `loc_x` int(11) NOT NULL COMMENT '目的地 X 座標',
  `loc_y` int(11) NOT NULL COMMENT '目的地 Y 座標',
  `map_id` smallint(5) UNSIGNED NOT NULL COMMENT '目的地地圖 ID',
  `heading` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '傳送後朝向 (0-7)',
  `price_amount` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '費用數量',
  `price_item_id` int(10) UNSIGNED NOT NULL DEFAULT 40308 COMMENT '費用物品 ID (預設金幣)',
  `min_level` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '最低等級限制 (0=無限制)',
  `max_level` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '最高等級限制 (0=無限制)',
  `require_quest_id` int(11) NOT NULL DEFAULT 0 COMMENT '所需任務',
  `require_step_min` int(11) NOT NULL DEFAULT 0 COMMENT 'step下限',
  `require_step_max` int(11) NOT NULL DEFAULT 0 COMMENT 'step上限',
  `require_item_id` int(11) NOT NULL DEFAULT 0 COMMENT '所需道具',
  `require_item_count` int(11) NOT NULL DEFAULT 0 COMMENT '所需數量',
  `deny_message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '不符提示',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '備註',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_npc_action_requirement`(`npc_id`, `action_name`, `require_item_id`) USING BTREE,
  INDEX `idx_npc_id`(`npc_id`) USING BTREE,
  INDEX `idx_action_name`(`action_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1259 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'NPC 傳送系統設定表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of npc_action_teleport
-- ----------------------------

-- ----------------------------
-- Table structure for npc_box
-- ----------------------------
DROP TABLE IF EXISTS `npc_box`;
CREATE TABLE `npc_box`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `npc_box_id` int(10) NOT NULL COMMENT '寶箱NPC編號',
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `type` int(2) NOT NULL DEFAULT 0 COMMENT '0:空, 1:道具, 2:怪物',
  `mob_id` int(10) NOT NULL DEFAULT 0 COMMENT '怪物編號',
  `item_id` int(10) NOT NULL DEFAULT 0 COMMENT '道具編號',
  `random` int(10) NOT NULL DEFAULT 0 COMMENT '機率權重 / 1000000',
  `count_min` int(10) NOT NULL DEFAULT 1 COMMENT '最小數量',
  `count_max` int(10) NOT NULL DEFAULT 1 COMMENT '最大數量',
  `is_broadcast` int(1) NOT NULL DEFAULT 0 COMMENT '是否廣播 0:否 1:是',
  `broadcast_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '內容格式 (%s=玩家, %s=地圖, %s=寶箱)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_npc_box_id`(`npc_box_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 91 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of npc_box
-- ----------------------------

-- ----------------------------
-- Table structure for npc_box_key
-- ----------------------------
DROP TABLE IF EXISTS `npc_box_key`;
CREATE TABLE `npc_box_key`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `npc_box_id` int(10) NOT NULL COMMENT '寶箱NPC編號',
  `key_id` int(10) NOT NULL COMMENT '需要的鑰匙道具編號',
  `type` int(2) NOT NULL DEFAULT 0 COMMENT '0:空, 1:道具, 2:怪物',
  `mob_id` int(10) NOT NULL DEFAULT 0 COMMENT '怪物編號',
  `item_id` int(10) NOT NULL DEFAULT 0 COMMENT '道具編號',
  `random` int(10) NOT NULL DEFAULT 0 COMMENT '機率權重 / 1000000',
  `count_min` int(10) NOT NULL DEFAULT 1 COMMENT '最小數量',
  `count_max` int(10) NOT NULL DEFAULT 1 COMMENT '最大數量',
  `is_broadcast` int(1) NULL DEFAULT 0 COMMENT '是否廣播 0:否 1:是',
  `broadcast_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '廣播內容 (%s=玩家, %s=地圖, %s=寶箱)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_npc_box_key_id`(`npc_box_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 64 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of npc_box_key
-- ----------------------------

-- ----------------------------
-- Table structure for npc_item_update
-- ----------------------------
DROP TABLE IF EXISTS `npc_item_update`;
CREATE TABLE `npc_item_update`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `itemid` int(10) NOT NULL DEFAULT 0 COMMENT '要升级的物品ITEMID',
  `toid` int(10) NOT NULL DEFAULT 0 COMMENT '可升级的物品ITEMID',
  `needids` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '40308' COMMENT '升级需要消耗的物品',
  `needcounts` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '升级需要消耗的物品数量',
  `other` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '说明',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 281 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of npc_item_update
-- ----------------------------

-- ----------------------------
-- Table structure for npc_touch
-- ----------------------------
DROP TABLE IF EXISTS `npc_touch`;
CREATE TABLE `npc_touch`  (
  `npc_id` int(11) NOT NULL COMMENT '觸發的 NPC 編號',
  `req_item_ids` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '需求材料 ID，逗號分隔',
  `req_item_counts` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '需求材料數量，逗號分隔',
  `is_consume` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否收取材料: 1=收取, 0=只檢查不扣除',
  `give_item_ids` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '給予的物品 ID，逗號分隔',
  `give_item_counts` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '給予的物品數量，逗號分隔',
  `skill_ids` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '給予的 Buff 技能 ID，逗號分隔（時間採技能原始設定）',
  `skill_chances` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '100' COMMENT '各技能成功機率(0~100)，逗號分隔，與 skill_ids 對應',
  `message` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '成功執行後的顯示訊息',
  `delete_after_touch` tinyint(1) NOT NULL DEFAULT 0 COMMENT '觸碰成功一次後是否刪除此 NPC(僅 L1NpcTouchInstance): 1=刪除, 0=保留',
  `delay_times` int(11) NOT NULL DEFAULT 0 COMMENT '觸發後休眠時間(秒)，此期間內點擊只收到 delay_message',
  `delay_message` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '休眠期間玩家點擊時發送的訊息',
  `mapid` int(11) NOT NULL DEFAULT -1 COMMENT '傳送目標地圖ID，-1=不傳送',
  `locx` int(11) NOT NULL DEFAULT 0 COMMENT '傳送目標X，與locy皆0時為地圖隨機座標',
  `locy` int(11) NOT NULL DEFAULT 0 COMMENT '傳送目標Y',
  PRIMARY KEY (`npc_id`) USING BTREE,
  INDEX `idx_npc_id`(`npc_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'NPC 觸碰/互動設定' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of npc_touch
-- ----------------------------

-- ----------------------------
-- Table structure for npcaction
-- ----------------------------
DROP TABLE IF EXISTS `npcaction`;
CREATE TABLE `npcaction`  (
  `npcid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `normal_action` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `caotic_action` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `teleport_url` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `teleport_urla` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`npcid`) USING BTREE,
  INDEX `idx_npcaction_npcid`(`npcid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of npcaction
-- ----------------------------

-- ----------------------------
-- Table structure for npcaction_teleport
-- ----------------------------
DROP TABLE IF EXISTS `npcaction_teleport`;
CREATE TABLE `npcaction_teleport`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '$',
  `orderid` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'A',
  `locx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `locy` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `mapid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `itemid` int(10) NOT NULL DEFAULT 40308,
  `price` int(10) NOT NULL DEFAULT 0,
  `user` int(10) NOT NULL DEFAULT 0,
  `min` int(10) NOT NULL DEFAULT 0,
  `max` int(10) NOT NULL DEFAULT 10,
  `note` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 436 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of npcaction_teleport
-- ----------------------------

-- ----------------------------
-- Table structure for npcchat
-- ----------------------------
DROP TABLE IF EXISTS `npcchat`;
CREATE TABLE `npcchat`  (
  `npc_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `chat_timing` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  `note` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `start_delay_time` int(10) NOT NULL DEFAULT 0,
  `chat_id1` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `chat_id2` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `chat_id3` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `chat_id4` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `chat_id5` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `chat_interval` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `is_shout` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  `is_world_chat` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  `is_repeat` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  `repeat_interval` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `game_time` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`npc_id`, `chat_timing`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of npcchat
-- ----------------------------

-- ----------------------------
-- Table structure for petitem
-- ----------------------------
DROP TABLE IF EXISTS `petitem`;
CREATE TABLE `petitem`  (
  `item_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `note` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `hitmodifier` int(3) NOT NULL DEFAULT 0,
  `dmgmodifier` int(3) NOT NULL DEFAULT 0,
  `ac` int(3) NOT NULL DEFAULT 0,
  `add_str` int(2) NOT NULL DEFAULT 0,
  `add_con` int(2) NOT NULL DEFAULT 0,
  `add_dex` int(2) NOT NULL DEFAULT 0,
  `add_int` int(2) NOT NULL DEFAULT 0,
  `add_wis` int(2) NOT NULL DEFAULT 0,
  `add_hp` int(10) NOT NULL DEFAULT 0,
  `add_mp` int(10) NOT NULL DEFAULT 0,
  `add_sp` int(10) NOT NULL DEFAULT 0,
  `m_def` int(2) NOT NULL DEFAULT 0,
  `isweapon` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  `ishigher` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 40767 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of petitem
-- ----------------------------

-- ----------------------------
-- Table structure for pettypes
-- ----------------------------
DROP TABLE IF EXISTS `pettypes`;
CREATE TABLE `pettypes`  (
  `BaseNpcId` int(10) NOT NULL,
  `Name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `CollarId` int(11) NOT NULL DEFAULT 0 COMMENT '項圈編號',
  `ChaCost` int(11) NOT NULL DEFAULT 6 COMMENT '寵物魅力消耗（領出時消耗的魅力值，預設6，虎/紀州犬系可設12）',
  `TameRate` int(11) NOT NULL DEFAULT 10000 COMMENT '抓取成功率萬分比（10000=100%，625=6.25%，HP<1/3時依此機率判定）',
  `ItemIdForTaming` int(10) NOT NULL COMMENT '抓取道具',
  `HpUpMin` int(10) NOT NULL,
  `HpUpMax` int(10) NOT NULL,
  `MpUpMin` int(10) NOT NULL,
  `MpUpMax` int(10) NOT NULL,
  `MinEvoLevel` int(11) NOT NULL DEFAULT 30 COMMENT '最低進化等級',
  `EvolutionItemId` int(11) NOT NULL DEFAULT 40070 COMMENT '進化道具',
  `NpcIdForEvolving` int(10) NOT NULL COMMENT '進化NPCid\",\"分隔,隨機分配',
  `MessageId1` int(10) NOT NULL,
  `MessageId2` int(10) NOT NULL,
  `MessageId3` int(10) NOT NULL,
  `MessageId4` int(10) NOT NULL,
  `MessageId5` int(10) NOT NULL,
  `DefyMessageId` int(10) NOT NULL,
  PRIMARY KEY (`BaseNpcId`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of pettypes
-- ----------------------------

-- ----------------------------
-- Table structure for poly_變身賦予能力
-- ----------------------------
DROP TABLE IF EXISTS `poly_變身賦予能力`;
CREATE TABLE `poly_變身賦予能力`  (
  `gfxId` int(10) NOT NULL COMMENT '變身圖檔編號 (對應 polymorphs.polyid)',
  `note` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '備註說明',
  `deadExp` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '1=死亡不掉落經驗值',
  `cancellation` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '1=相消術不移除變身',
  `addStr` tinyint(4) NOT NULL DEFAULT 0,
  `addDex` tinyint(4) NOT NULL DEFAULT 0,
  `addCon` tinyint(4) NOT NULL DEFAULT 0,
  `addInt` tinyint(4) NOT NULL DEFAULT 0,
  `addWis` tinyint(4) NOT NULL DEFAULT 0,
  `addCha` tinyint(4) NOT NULL DEFAULT 0,
  `addAc` int(5) NOT NULL DEFAULT 0 COMMENT '防禦力(正值=加防禦)',
  `addMaxHp` int(5) NOT NULL DEFAULT 0,
  `addMaxMp` int(5) NOT NULL DEFAULT 0,
  `addHpr` int(5) NOT NULL DEFAULT 0,
  `addMpr` int(5) NOT NULL DEFAULT 0,
  `addDmg` int(5) NOT NULL DEFAULT 0,
  `addBowDmg` int(5) NOT NULL DEFAULT 0,
  `addHit` int(5) NOT NULL DEFAULT 0,
  `addBowHit` int(5) NOT NULL DEFAULT 0,
  `reduction_dmg` int(5) NOT NULL DEFAULT 0 COMMENT '物理傷害減免',
  `reduction_magic_dmg` int(5) NOT NULL DEFAULT 0 COMMENT '魔法傷害減免',
  `addMr` int(5) NOT NULL DEFAULT 0,
  `addSp` int(5) NOT NULL DEFAULT 0,
  `addFire` int(5) NOT NULL DEFAULT 0,
  `addWind` int(5) NOT NULL DEFAULT 0,
  `addEarth` int(5) NOT NULL DEFAULT 0,
  `addWater` int(5) NOT NULL DEFAULT 0,
  `addExpRate` int(5) NOT NULL DEFAULT 0 COMMENT '經驗獲取率 (例: 150=15%)',
  PRIMARY KEY (`gfxId`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '變身能力附加表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of poly_變身賦予能力
-- ----------------------------

-- ----------------------------
-- Table structure for polymorphs
-- ----------------------------
DROP TABLE IF EXISTS `polymorphs`;
CREATE TABLE `polymorphs`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `polyid` int(11) NULL DEFAULT NULL,
  `minlevel` int(11) NULL DEFAULT NULL,
  `weaponequip` int(11) NULL DEFAULT NULL,
  `armorequip` int(11) NULL DEFAULT NULL,
  `isSkillUse` int(11) NULL DEFAULT NULL,
  `cause` int(11) NULL DEFAULT NULL,
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `arrow_spr` int(11) NOT NULL DEFAULT -1 COMMENT '變身遠程攻擊箭矢/飛刀 GFX；-1=不控制',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 25744 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'MyISAM free: 10240 kB' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of polymorphs
-- ----------------------------

-- ----------------------------
-- Table structure for server_挖礦
-- ----------------------------
DROP TABLE IF EXISTS `server_挖礦`;
CREATE TABLE `server_挖礦`  (
  `tool_item_id` int(11) NOT NULL COMMENT '挖礦道具ID',
  `get_item_id` int(11) NOT NULL COMMENT '獲得物品ID',
  `count` int(11) NOT NULL DEFAULT 1 COMMENT '數量',
  `chance` int(11) NOT NULL DEFAULT 1000 COMMENT '機率(1~1000000)',
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物品名称',
  PRIMARY KEY (`tool_item_id`, `get_item_id`) USING BTREE,
  INDEX `idx_tool`(`tool_item_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '挖礦掉落' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of server_挖礦
-- ----------------------------

-- ----------------------------
-- Table structure for server_釣魚
-- ----------------------------
DROP TABLE IF EXISTS `server_釣魚`;
CREATE TABLE `server_釣魚`  (
  `fishingpole` int(10) NOT NULL DEFAULT 0 COMMENT '釣竿ID',
  `itemid` int(10) NOT NULL DEFAULT 0 COMMENT '可獲得物品ID',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '備註',
  `random` int(10) NOT NULL DEFAULT 0 COMMENT '機率(同竿加總=1000000，未滿則餘數=不成功仍扣餌)',
  `count` int(10) NOT NULL DEFAULT 1 COMMENT '可獲得的物品數量',
  `bait` int(10) NOT NULL DEFAULT 0 COMMENT '扣除的魚餌數量',
  PRIMARY KEY (`fishingpole`, `itemid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '釣魚漁獲' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_釣魚
-- ----------------------------

-- ----------------------------
-- Table structure for server_event
-- ----------------------------
DROP TABLE IF EXISTS `server_event`;
CREATE TABLE `server_event`  (
  `id` int(10) NOT NULL,
  `eventname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `eventclass` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `eventstart` tinyint(1) NOT NULL DEFAULT 0,
  `eventother` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '说明:',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_event
-- ----------------------------

-- ----------------------------
-- Table structure for shop
-- ----------------------------
DROP TABLE IF EXISTS `shop`;
CREATE TABLE `shop`  (
  `npc_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `item_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `order_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `selling_price` int(10) NOT NULL DEFAULT -1 COMMENT 'NPC販售價格',
  `pack_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '數量',
  `purchasing_price` int(10) NOT NULL DEFAULT -1 COMMENT 'NPC收購價格',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '道具名稱備註',
  `daily_buy_limit` int(11) NOT NULL DEFAULT 0 COMMENT '每日限購數量 (0=不限制)',
  PRIMARY KEY (`npc_id`, `item_id`, `order_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = FIXED;

-- ----------------------------
-- Records of shop
-- ----------------------------

-- ----------------------------
-- Table structure for shop_cn
-- ----------------------------
DROP TABLE IF EXISTS `shop_cn`;
CREATE TABLE `shop_cn`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `npc_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `item_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `order_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序序號（商店顯示順序）',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `selling_price` int(10) NOT NULL DEFAULT 1,
  `pack_count` int(10) UNSIGNED NOT NULL DEFAULT 1,
  `daily_buy_limit` int(11) NOT NULL DEFAULT 0 COMMENT '每日限購數量 (0=不限制)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1792 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of shop_cn
-- ----------------------------

-- ----------------------------
-- Table structure for skill_傷害天賦設置
-- ----------------------------
DROP TABLE IF EXISTS `skill_傷害天賦設置`;
CREATE TABLE `skill_傷害天賦設置`  (
  `talent_id` int(11) NOT NULL COMMENT '天賦ID (1-30)',
  `skill_id` int(11) NOT NULL COMMENT '對應技能ID (0=全技能通用)',
  `note` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '備註說明',
  `class_limit` int(11) NOT NULL DEFAULT 127 COMMENT '職業位元限制：127=全職；1王族2騎4精8法16黑32龍64幻',
  `upgrade_item_id` int(11) NOT NULL DEFAULT 0 COMMENT '升級消耗道具 itemid，0=不要求',
  `upgrade_item_count` int(11) NOT NULL DEFAULT 0 COMMENT '消耗數量',
  `upgrade_char_level` int(11) NOT NULL DEFAULT 0 COMMENT '角色等級下限，0=不限制',
  `talent_point` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '升至此等所需天賦點數',
  `talent_level` tinyint(4) NOT NULL COMMENT '天賦等級 (1-5)',
  `add_damage` int(11) NOT NULL DEFAULT 0 COMMENT '額外固定傷害',
  `stun_prob` int(11) NOT NULL DEFAULT 0 COMMENT '暈眩觸發機率 (0-100)',
  `stun_sec` int(11) NOT NULL DEFAULT 0 COMMENT '暈眩持續秒數',
  PRIMARY KEY (`talent_id`, `talent_level`) USING BTREE,
  INDEX `idx_skill`(`skill_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '技能天賦-傷害增幅與暈眩' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of skill_傷害天賦設置
-- ----------------------------

-- ----------------------------
-- Table structure for skill_狀態天賦設置
-- ----------------------------
DROP TABLE IF EXISTS `skill_狀態天賦設置`;
CREATE TABLE `skill_狀態天賦設置`  (
  `talent_id` int(11) NOT NULL COMMENT '天賦ID (自訂,不可與skill_傷害天賦設置衝突)',
  `skill_id` int(11) NOT NULL COMMENT '對應 Buff 技能ID',
  `note` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '備註說明',
  `class_limit` int(11) NOT NULL DEFAULT 127 COMMENT '職業位元限制：127=全職；1王族2騎4精8法16黑32龍64幻',
  `upgrade_item_id` int(11) NOT NULL DEFAULT 0 COMMENT '升級消耗道具 itemid，0=不要求',
  `upgrade_item_count` int(11) NOT NULL DEFAULT 0 COMMENT '消耗數量',
  `upgrade_char_level` int(11) NOT NULL DEFAULT 0 COMMENT '角色等級下限，0=不限制',
  `talent_point` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '升至此等所需天賦點數',
  `talent_level` tinyint(4) NOT NULL COMMENT '天賦等級 (自訂)',
  `add_hp` int(11) NOT NULL DEFAULT 0 COMMENT 'HP 上限',
  `add_mp` int(11) NOT NULL DEFAULT 0 COMMENT 'MP 上限',
  `add_sp` int(11) NOT NULL DEFAULT 0 COMMENT 'SP (魔攻)',
  `add_str` int(11) NOT NULL DEFAULT 0 COMMENT '力量',
  `add_dex` int(11) NOT NULL DEFAULT 0 COMMENT '敏捷',
  `add_con` int(11) NOT NULL DEFAULT 0 COMMENT '體質',
  `add_int` int(11) NOT NULL DEFAULT 0 COMMENT '智力',
  `add_wis` int(11) NOT NULL DEFAULT 0 COMMENT '精神',
  `add_cha` int(11) NOT NULL DEFAULT 0 COMMENT '魅力',
  `add_mr` int(11) NOT NULL DEFAULT 0 COMMENT '魔法防禦',
  `add_ac` int(11) NOT NULL DEFAULT 0 COMMENT '防禦力',
  `add_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '近戰傷害',
  `add_bow_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '遠程傷害',
  `add_hit` int(11) NOT NULL DEFAULT 0 COMMENT '近戰命中',
  `add_bow_hit` int(11) NOT NULL DEFAULT 0 COMMENT '遠程命中',
  `add_hpr` int(11) NOT NULL DEFAULT 0 COMMENT 'HP 恢復',
  `add_mpr` int(11) NOT NULL DEFAULT 0 COMMENT 'MP 恢復',
  `add_melee_redux` int(11) NOT NULL DEFAULT 0 COMMENT '近戰減傷',
  `add_bow_redux` int(11) NOT NULL DEFAULT 0 COMMENT '遠程減傷',
  `add_pvp_dmg` int(11) NOT NULL DEFAULT 0 COMMENT 'PVP 傷害加成',
  `add_pvp_redux` int(11) NOT NULL DEFAULT 0 COMMENT 'PVP 傷害減免',
  `add_dmg_boss` int(11) NOT NULL DEFAULT 0 COMMENT 'Boss 傷害加成',
  `add_boss_redux` int(11) NOT NULL DEFAULT 0 COMMENT 'Boss 傷害減免',
  `add_ignore_reduction` int(11) NOT NULL DEFAULT 0 COMMENT '無視減傷',
  `add_adena_rate` int(11) NOT NULL DEFAULT 0 COMMENT '金幣掉落率 (%)',
  `add_drop_rate` int(11) NOT NULL DEFAULT 0 COMMENT '物品掉落率 (%)',
  `add_exp_rate` int(11) NOT NULL DEFAULT 0 COMMENT '經驗值獲取率 (%)',
  `add_def_fire` int(11) NOT NULL DEFAULT 0 COMMENT '火屬性防禦',
  `add_def_water` int(11) NOT NULL DEFAULT 0 COMMENT '水屬性防禦',
  `add_def_wind` int(11) NOT NULL DEFAULT 0 COMMENT '風屬性防禦',
  `add_def_earth` int(11) NOT NULL DEFAULT 0 COMMENT '地屬性防禦',
  `add_regist_freeze` int(11) NOT NULL DEFAULT 0 COMMENT '冰凍耐性',
  `add_regist_stone` int(11) NOT NULL DEFAULT 0 COMMENT '石化耐性',
  `add_regist_sleep` int(11) NOT NULL DEFAULT 0 COMMENT '睡眠耐性',
  `add_regist_blind` int(11) NOT NULL DEFAULT 0 COMMENT '暗黑耐性',
  `add_regist_stun` int(11) NOT NULL DEFAULT 0 COMMENT '暈眩耐性',
  `add_regist_sustain` int(11) NOT NULL DEFAULT 0 COMMENT '支撐耐性',
  PRIMARY KEY (`talent_id`, `talent_level`) USING BTREE,
  INDEX `idx_skill`(`skill_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '技能天賦-Buff 狀態增幅' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of skill_狀態天賦設置
-- ----------------------------

-- ----------------------------
-- Table structure for skills
-- ----------------------------
DROP TABLE IF EXISTS `skills`;
CREATE TABLE `skills`  (
  `skill_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `effect_skill_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '資料庫定義的效果或 SkillMode 對應 ID，0=使用自身 skill_id',
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `skill_level` int(10) NOT NULL DEFAULT 0,
  `skill_number` int(10) NOT NULL DEFAULT 0,
  `mpConsume` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `hpConsume` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `itemConsumeId` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `itemConsumeCount` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `reuseDelay` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `buffDuration` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `target` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `target_to` int(10) NOT NULL DEFAULT 0 COMMENT '技能施放目標[0=自己；1=人物；2=NPC；4=血盟；8=組隊；16=寵物；32=地點；編號相加=多種目標]',
  `damage_value` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `damage_dice` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `damage_dice_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `probability_value` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `probability_dice` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `attr` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `type` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `lawful` int(10) NOT NULL DEFAULT 0,
  `ranged` int(10) NOT NULL DEFAULT 0,
  `area` int(10) NOT NULL DEFAULT 0,
  `through` int(10) NOT NULL DEFAULT 0,
  `id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `nameid` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `action_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `castgfx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `castgfx2` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `sysmsgID_happen` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `sysmsgID_stop` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `sysmsgID_fail` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`skill_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 101422 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'MyISAM free: 10240 kB; MyISAM free: 10240 kB' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of skills
-- ----------------------------

-- ----------------------------
-- Table structure for skills_相消免疫技能
-- ----------------------------
DROP TABLE IF EXISTS `skills_相消免疫技能`;
CREATE TABLE `skills_相消免疫技能`  (
  `skill_id` int(10) NOT NULL COMMENT '技能編號(skill_id，對應 skills 表)',
  `note` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '名稱備註(程式不讀取，僅供管理員辨識)',
  PRIMARY KEY (`skill_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '玩家技能：不受魔法相消術影響。非玩家技能(禁言/詛咒等)仍硬編碼於程式中' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of skills_相消免疫技能
-- ----------------------------

-- ----------------------------
-- Table structure for skills_相消怪物轉換
-- ----------------------------
DROP TABLE IF EXISTS `skills_相消怪物轉換`;
CREATE TABLE `skills_相消怪物轉換`  (
  `npc_id` int(10) UNSIGNED NOT NULL COMMENT '受到相消術的來源NPC編號',
  `npcname` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `transform_type` tinyint(3) UNSIGNED NOT NULL COMMENT '1=轉換外型；2=重生怪物',
  `target_id` int(10) UNSIGNED NOT NULL COMMENT '方式1=目標GFX；方式2=目標NPC編號',
  `duration_seconds` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '方式2重生怪物存活秒數；0=不限制',
  `new_name_id` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '方式1可選的新名稱ID；空白=不變',
  `new_passispeed` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '方式1可選的新移動間隔；0=不變',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`npc_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '魔法相消術NPC與怪物轉換' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of skills_相消怪物轉換
-- ----------------------------

-- ----------------------------
-- Table structure for skills_負面技能控制
-- ----------------------------
DROP TABLE IF EXISTS `skills_負面技能控制`;
CREATE TABLE `skills_負面技能控制`  (
  `skill_id` int(11) NOT NULL COMMENT '技能編號 (對應 skills 表)',
  `note` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '說明備註 (技能名稱或管理用，程式不讀取)',
  `prob_high` int(11) NOT NULL DEFAULT 50 COMMENT '我方等級 > 對方時的基礎機率 (%)',
  `prob_equal` int(11) NOT NULL DEFAULT 40 COMMENT '等級相同時的基礎機率 (%)',
  `prob_low` int(11) NOT NULL DEFAULT 30 COMMENT '我方等級 < 對方時的基礎機率 (%)',
  `bonus_str` double NOT NULL DEFAULT 0 COMMENT '力量倍率 (素質 × 倍率加入機率)',
  `bonus_dex` double NOT NULL DEFAULT 0 COMMENT '敏捷倍率',
  `bonus_int` double NOT NULL DEFAULT 0 COMMENT '智力倍率',
  `check_resist_type` int(11) NOT NULL DEFAULT 0 COMMENT '耐性類型: 1=寒冰, 2=石化, 3=睡眠, 4=暗黑, 5=昏迷, 6=支撐, 0=無',
  `check_magic_level` tinyint(1) NOT NULL DEFAULT 1 COMMENT '魔法等級: 0=不計算 1=計入機率',
  `check_magic_hit` tinyint(1) NOT NULL DEFAULT 1 COMMENT '魔法命中: 0=不計算 1=計入機率',
  `mr_multiplier` double NOT NULL DEFAULT 0.05 COMMENT '目標 MR 減免倍率 (MR × 此值 從機率扣除，建議 0.01~0.02)',
  `con_multiplier` double NOT NULL DEFAULT 0 COMMENT '目標體質/X 減免被命中機率，0=不計算',
  `wis_multiplier` double NOT NULL DEFAULT 0 COMMENT '目標精神/X 減免被命中機率，0=不計算',
  PRIMARY KEY (`skill_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '技能魔法命中機率設定' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of skills_負面技能控制
-- ----------------------------

-- ----------------------------
-- Table structure for skills_負面boss免疫
-- ----------------------------
DROP TABLE IF EXISTS `skills_負面boss免疫`;
CREATE TABLE `skills_負面boss免疫`  (
  `skill_id` int(11) NOT NULL COMMENT '技能編號',
  `note` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '名稱備註(程式不讀取，僅供管理員辨識)',
  `modifier` int(11) NOT NULL DEFAULT 0 COMMENT '0=完全免疫；>0=封頂後機率÷該整數',
  PRIMARY KEY (`skill_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'BOSS 負面技能免疫／機率削減（BossSkillImmuneTable）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of skills_負面boss免疫
-- ----------------------------

-- ----------------------------
-- Table structure for skills_魔屏無效技能
-- ----------------------------
DROP TABLE IF EXISTS `skills_魔屏無效技能`;
CREATE TABLE `skills_魔屏無效技能`  (
  `skill_id` int(10) NOT NULL COMMENT '技能編號(skill_id，對應 skills 表)',
  `note` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '名稱備註(程式不讀取，僅供管理員辨識)',
  PRIMARY KEY (`skill_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '魔法屏障(COUNTER_MAGIC)無法抵銷的技能。可自訂新增，與硬編碼清單合併生效' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of skills_魔屏無效技能
-- ----------------------------

-- ----------------------------
-- Table structure for skills_buff_ability
-- ----------------------------
DROP TABLE IF EXISTS `skills_buff_ability`;
CREATE TABLE `skills_buff_ability`  (
  `skill_id` int(11) NOT NULL COMMENT '技能 ID (對應 L1SkillId)',
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `ability_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '屬性類型 (對應 ItemAbility.AbilityType)',
  `ability_value` int(11) NOT NULL COMMENT '屬性數值 (正數為加成，負數為減少)',
  PRIMARY KEY (`skill_id`, `ability_type`) USING BTREE,
  INDEX `idx_skill_id`(`skill_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '技能 Buff 屬性加成表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of skills_buff_ability
-- ----------------------------

-- ----------------------------
-- Table structure for skills_buff_ability_註冊能力
-- ----------------------------
DROP TABLE IF EXISTS `skills_buff_ability_註冊能力`;
CREATE TABLE `skills_buff_ability_註冊能力`  (
  `ability_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '屬性類型 (須與程式枚舉名稱完全一致)',
  `說明` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '能力說明',
  `範例` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '建議範例值或說明',
  PRIMARY KEY (`ability_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'skills_buff_ability 可用的 ability_type 參考表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of skills_buff_ability_註冊能力
-- ----------------------------

-- ----------------------------
-- Table structure for skills_item
-- ----------------------------
DROP TABLE IF EXISTS `skills_item`;
CREATE TABLE `skills_item`  (
  `skill_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `itemids` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `counts` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`skill_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 101422 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'MyISAM free: 10240 kB; MyISAM free: 10240 kB' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of skills_item
-- ----------------------------

-- ----------------------------
-- Table structure for spawnlist
-- ----------------------------
DROP TABLE IF EXISTS `spawnlist`;
CREATE TABLE `spawnlist`  (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT '出生設定流水號（主鍵）',
  `location` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '區域／說明用文字（僅供辨識，程式邏輯未使用）',
  `count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '同時存在數量（載入時會依地圖怪物量倍率再計算）',
  `npc_templateid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'NPC 樣板編號（對應 npc 表）',
  `group_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '怪物群組編號；0 表示不屬於群組',
  `locx` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '出生中心 X（定點或搭配 randomx／y）',
  `locy` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '出生中心 Y（定點或搭配 randomx／y）',
  `randomx` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '以中心為基準的 X 向隨機偏移範圍（格）',
  `randomy` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '以中心為基準的 Y 向隨機偏移範圍（格）',
  `locx1` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '矩形範圍出生：角1 X；全為 0 則非矩形模式',
  `locy1` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '矩形範圍出生：角1 Y',
  `locx2` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '矩形範圍出生：角2 X',
  `locy2` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '矩形範圍出生：角2 Y',
  `heading` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '出生面向（0–7）',
  `min_respawn_delay` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '重生延遲下限（秒）',
  `max_respawn_delay` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '重生延遲上限（秒）；與下限取隨機',
  `mapid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '地圖編號',
  `respawn_screen` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '重生時是否套用「畫面／可見玩家」相關判定（對應 isRespawnScreen）',
  `movement_distance` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '召喚後 NPC 遊走距離（傳入 movementDistance）',
  `rest` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '出生後是否暫停行動（對應 isRest）',
  `near_spawn` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '召喚模式：0 一般；1 閃避週邊 PC（對應 setSpawnType）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 400826 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '一般野外怪物／NPC 出生點設定；對應程式 SpawnTable／L1Spawn' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of spawnlist
-- ----------------------------

-- ----------------------------
-- Table structure for spawnlist_定時
-- ----------------------------
DROP TABLE IF EXISTS `spawnlist_定時`;
CREATE TABLE `spawnlist_定時`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `week` int(11) NOT NULL DEFAULT 0 COMMENT '0=每天, 1~7=週一到週日',
  `hour` int(11) NOT NULL DEFAULT 0 COMMENT '24小時制',
  `minute` int(11) NOT NULL DEFAULT 0 COMMENT '分鐘',
  `npcid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'NPC ID',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '備註用',
  `count` int(10) UNSIGNED NOT NULL DEFAULT 1 COMMENT '數量',
  `loc_x` int(11) NOT NULL DEFAULT 0 COMMENT '出生座標 X',
  `loc_y` int(11) NOT NULL DEFAULT 0 COMMENT '出生座標 Y',
  `loc_map` int(11) NOT NULL DEFAULT 0 COMMENT '出生地圖 ID',
  `random_range` int(11) NOT NULL DEFAULT 0 COMMENT '隨機範圍 (0=定點)',
  `message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '公告內容',
  `effect` int(11) NOT NULL DEFAULT 0 COMMENT '畫面特效; 0=不發特效封包; 1=閃爍紫框/2=震動/3=煙火/4=雷雨/5=飽食閃爍/6=藍框/7=火焰框/8=白框',
  `exist_time` int(11) NOT NULL DEFAULT 0 COMMENT '存活秒數, 0=不回收',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_week_hour_minute`(`week`, `hour`, `minute`) USING BTREE COMMENT '定時查詢索引'
) ENGINE = MyISAM AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '定時怪物出生' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of spawnlist_定時
-- ----------------------------

-- ----------------------------
-- Table structure for spawnlist_door
-- ----------------------------
DROP TABLE IF EXISTS `spawnlist_door`;
CREATE TABLE `spawnlist_door`  (
  `id` int(11) NOT NULL DEFAULT 0,
  `location` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `gfxid` int(11) NOT NULL DEFAULT 0,
  `locx` int(11) NOT NULL DEFAULT 0,
  `locy` int(11) NOT NULL DEFAULT 0,
  `mapid` int(11) NOT NULL DEFAULT 0,
  `direction` int(11) NOT NULL DEFAULT 0,
  `left_edge_location` int(11) NOT NULL DEFAULT 0,
  `right_edge_location` int(11) NOT NULL DEFAULT 0,
  `hp` int(11) NOT NULL DEFAULT 0,
  `keeper` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of spawnlist_door
-- ----------------------------

-- ----------------------------
-- Table structure for spawnlist_light
-- ----------------------------
DROP TABLE IF EXISTS `spawnlist_light`;
CREATE TABLE `spawnlist_light`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `npcid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `locx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `locy` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `mapid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 234 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = FIXED;

-- ----------------------------
-- Records of spawnlist_light
-- ----------------------------

-- ----------------------------
-- Table structure for spawnlist_npc
-- ----------------------------
DROP TABLE IF EXISTS `spawnlist_npc`;
CREATE TABLE `spawnlist_npc`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `location` varchar(19) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `npc_templateid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `locx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `locy` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `randomx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `randomy` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `heading` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `respawn_delay` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `mapid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `movement_distance` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1337 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of spawnlist_npc
-- ----------------------------

-- ----------------------------
-- Table structure for spawnlist_npc_box
-- ----------------------------
DROP TABLE IF EXISTS `spawnlist_npc_box`;
CREATE TABLE `spawnlist_npc_box`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `location` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '說明/地點名稱',
  `count` int(11) NOT NULL DEFAULT 1 COMMENT '數量',
  `npc_templateid` int(11) NOT NULL DEFAULT 0 COMMENT '寶箱NPC編號',
  `locx` int(11) NOT NULL DEFAULT 0 COMMENT 'X座標(中心)',
  `locy` int(11) NOT NULL DEFAULT 0 COMMENT 'Y座標(中心)',
  `random` int(11) NOT NULL DEFAULT 0 COMMENT '隨機範圍(半徑)',
  `locx1` int(11) NOT NULL DEFAULT 0 COMMENT '矩形區域 X1 (可選)',
  `locy1` int(11) NOT NULL DEFAULT 0 COMMENT '矩形區域 Y1 (可選)',
  `locx2` int(11) NOT NULL DEFAULT 0 COMMENT '矩形區域 X2 (可選)',
  `locy2` int(11) NOT NULL DEFAULT 0 COMMENT '矩形區域 Y2 (可選)',
  `min_respawn_delay` int(11) NOT NULL DEFAULT 60 COMMENT '最小重生時間(秒) 10秒為單為佳',
  `max_respawn_delay` int(11) NOT NULL DEFAULT 120 COMMENT '最大重生時間(秒) 10秒為單為佳',
  `mapid` int(11) NOT NULL DEFAULT 0 COMMENT '地圖編號',
  `heading` int(11) NOT NULL DEFAULT 0 COMMENT '面向 (0-7)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `key_mapid`(`mapid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 207 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of spawnlist_npc_box
-- ----------------------------

