DROP TABLE IF EXISTS `spawnlist_time`;
CREATE TABLE `spawnlist_time`  (
  `npc_id` int(11) NOT NULL,
  `time_start` time NULL DEFAULT NULL,
  `time_end` time NULL DEFAULT NULL,
  `delete_at_endtime` tinyint(1) NOT NULL DEFAULT 0 COMMENT '時段結束是否清除已出生的npc 0:不清 , 1:清除',
  `note` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '備註欄位（開發/管理用）',
  PRIMARY KEY (`npc_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = FIXED;

